và dùng AI có trách nhiệm.","subject":"Kỹ năng số","icon_key":"verified_user_outlined","action_label":"Điều tra một thông tin"}],"activities":[{"id":"logic-balance","topic_id":"logic","position":0,"content_version":1,"title":"Chiếc cân bí mật","stage":"Khám phá","prompt":"Một hộp nặng bằng 4 khối. Thả khối vào đĩa trống để cân bằng.","hint_levels":["Mỗi khối nặng 1 đơn vị. Quan sát độ nghiêng của cân."],"explanation":"Hai bên cùng nặng 4 đơn vị nên cân thăng bằng.","mechanism":"balanceBlocks","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"blocks":0},"skill_ids":[]},{"id":"logic-remove","topic_id":"logic","position":1,"content_version":1,"title":"Bóc từng lớp","stage":"Khám phá","prompt":"x + 3 = 7. Vuốt bỏ từng cặp khối ở hai vế để tìm x.","hint_levels":["Mỗi lần bỏ cùng 1 khối ở cả hai bên, đẳng thức vẫn đúng."],"explanation":"Bỏ 3 ở cả hai vế: x = 4.","mechanism":"removeBothSides","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"pairs":0},"skill_ids":[]},{"id":"logic-gears","topic_id":"logic","position":2,"content_version":1,"title":"Truyền chuyển động","stage":"Khám phá","prompt":"Bánh nhỏ có 12 răng, bánh lớn có 24 răng. Xoay bánh nhỏ để bánh lớn quay đúng một vòng.","hint_levels":["Bánh lớn cần số răng gấp đôi bánh nhỏ đi qua điểm tiếp xúc."],"explanation":"Bánh 12 răng quay 2 vòng thì bánh 24 răng quay 1 vòng, theo chiều ngược lại.","mechanism":"gearRatios","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"turns":0},"skill_ids":[]},{"id":"logic-invariant","topic_id":"logic","position":3,"content_version":1,"title":"Giữ nguyên sự cân bằng","stage":"Vận dụng","prompt":"Mô hình đang biểu diễn x + 5 = 9. Giữ cân bằng và cô lập x bằng cách bỏ cùng một lượng ở hai vế.","hint_levels":["Quan sát lượng còn cộng với x. Mỗi thao tác phải giữ hai vế bằng nhau."],"explanation":"Bớt 5 ở cả hai vế bảo toàn đẳng thức: x = 4. Giá trị thay đổi, quy tắc cân bằng vẫn giữ nguyên.","mechanism":"removeBothSides","mechanism_version":1,"evaluator_version":1,"config":{"extra":5,"total":9},"initial_state":{"pairs":0},"skill_ids":[]},{"id":"logic-hidden","topic_id":"logic","position":4,"content_version":1,"title":"Hiệu chuẩn hộp bí mật","stage":"Thử thách","prompt":"Hộp mới có khối lượng khác trước. Thêm hoặc lấy khối đơn vị để tìm lúc cân nằm ngang.","hint_levels":["Dùng chiều nghiêng làm phản hồi; khi thêm quá nhiều, hãy lấy bớt."],"explanation":"Cân bằng cho thấy hai bên có cùng khối lượng: hộp này bằng 6 khối đơn vị.","mechanism":"balanceBlocks","mechanism_version":1,"evaluator_version":1,"config":{"target":6},"initial_state":{"blocks":1},"skill_ids":[]},{"id":"logic-counterexample","topic_id":"logic","position":5,"content_version":1,"title":"Một trường hợp đủ để bác bỏ","stage":"Thử thách","prompt":"Có người nói: “Đèn A sáng thì đèn B luôn sáng”. Bật/tắt hai đèn để tạo một phản ví dụ.","hint_levels":["Muốn bác bỏ quy tắc, điều kiện đầu phải xảy ra nhưng kết luận không xảy ra."],"explanation":"A sáng và B tắt là phản ví dụ. Khi A tắt, trường hợp đó không bác bỏ mệnh đề “nếu A thì B”.","mechanism":"logicalCounterexample","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"a":false,"b":false},"skill_ids":[]},{"id":"logic-investigate","topic_id":"logic","position":6,"content_version":1,"title":"Từ quy luật đến phản ví dụ","stage":"Vận dụng","prompt":"Sắp xếp quy trình kiểm tra một quy luật được phỏng đoán.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Một vài ví dụ đúng chưa chứng minh mệnh đề tổng quát; phản ví dụ có thể bác bỏ nó.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Tìm trường hợp có thể bác bỏ.","Quan sát vài ví dụ.","Nêu phỏng đoán.","Sửa hoặc chứng minh phỏng đoán."],"target":[1,2,0,3]},"initial_state":{"values":[0,1,2,3]},"skill_ids":["logic.transfer"]},{"id":"logic-counterexample-transfer","topic_id":"logic","position":7,"content_version":1,"title":"Phản ví dụ có sức mạnh gì?","stage":"Thử thách","prompt":"Mệnh đề: “Mọi số chẵn đều chia hết cho 4.” Chọn các phản ví dụ.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"6 và 10 chẵn nhưng không chia hết cho 4. Chỉ cần một phản ví dụ đã bác bỏ mệnh đề mọi.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["6","8","10","12"],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["logic.transfer"]},{"id":"math-paint","topic_id":"math","position":0,"content_version":1,"title":"Miếng bánh của bạn","stage":"Khám phá","prompt":"Tô đúng 3/8 chiếc bánh. Chạm vào các lát để bật hoặc tắt màu.","hint_levels":["Mẫu số 8 cho biết chiếc bánh có 8 phần bằng nhau."],"explanation":"Ba phần trong tám phần bằng nhau biểu diễn 3/8.","mechanism":"fractionPaint","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"painted":[]},"skill_ids":["fractions.part-whole"]},{"id":"math-fold","topic_id":"math","position":1,"content_version":1,"title":"Gấp để chia","stage":"Khám phá","prompt":"Gấp tờ giấy thành những phần bằng nhau, để mỗi phần bằng 1/4 tờ ban đầu.","hint_levels":["Mỗi lần gấp đôi làm số phần tăng gấp đôi."],"explanation":"Hai lần gấp đôi tạo 4 phần bằng nhau: mỗi phần bằng 1/4.","mechanism":"fractionFold","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"folds":0},"skill_ids":["fractions.equal-parts"]},{"id":"math-share","topic_id":"math","position":2,"content_version":1,"title":"Chuyến picnic","stage":"Khám phá","prompt":"Chia đều 9 quả cam vào 3 giỏ. Kéo từng quả đến giỏ bạn muốn.","hint_levels":["Mọi giỏ phải có cùng số quả và không còn quả bên ngoài."],"explanation":"9 chia 3 bằng 3: mỗi giỏ có 3 quả cam.","mechanism":"distributeObjects","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"baskets":[0,0,0]},"skill_ids":["fractions.equal-parts"]},{"id":"math-equivalent","topic_id":"math","position":3,"content_version":1,"title":"Một phân số, hai cách viết","stage":"Vận dụng","prompt":"Biểu diễn 3/4 chiếc bánh. Tự tô trên chiếc bánh chia 8 lát bằng nhau.","hint_levels":["Đổi về những phần có mẫu số 8. Có thể chạm lại để bỏ màu một lát."],"explanation":"Phần tô là 6/8; phần chưa tô là 2/8. Một tổng thể cho phép diễn tả cả phần và phần bù.","mechanism":"fractionPaint","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"painted":[]},"skill_ids":[]},{"id":"math-complement","topic_id":"math","position":4,"content_version":1,"title":"Tìm phần còn lại","stage":"Vận dụng","prompt":"Tô sao cho phần CHƯA tô chiếm 3/8 chiếc bánh. Tự tô trên chiếc bánh chia 8 lát bằng nhau.","hint_levels":["Đổi về những phần có mẫu số 8. Có thể chạm lại để bỏ màu một lát."],"explanation":"Phần tô là 5/8; phần chưa tô là 3/8. Một tổng thể cho phép diễn tả cả phần và phần bù.","mechanism":"fractionPaint","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"painted":[]},"skill_ids":[]},{"id":"math-number-line","topic_id":"math","position":5,"content_version":2,"title":"Phân số có một vị trí","stage":"Vận dụng","prompt":"Đặt điểm tại 3/4 đoạn đường từ 0 đến 1. Mỗi nấc là 1/8.","hint_levels":["Chia đoạn thành 4 phần bằng nhau rồi đi 3 phần. Hai nấc nhỏ tạo một phần tư."],"explanation":"3/4 = 6/8. Phân số biểu diễn một vị trí trên trục số, không chỉ là phần tô của chiếc bánh.","mechanism":"fractionNumberLine","mechanism_version":1,"evaluator_version":2,"config":{},"initial_state":{"position":0},"skill_ids":["fractions.part-whole"]},{"id":"math-percent-transfer","topic_id":"math","position":6,"content_version":1,"title":"Một lượng, nhiều cách viết","stage":"Vận dụng","prompt":"Ghép phân số với dạng tương đương.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Đổi phần trăm bằng cách quy về mẫu 100. Phân số bằng nhau biểu diễn cùng tỷ lệ.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["1/2","3/4","1/4"],"choices":["25%","50%","75%"],"target":[1,2,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["math.transfer"]},{"id":"math-comparison","topic_id":"math","position":7,"content_version":1,"title":"So sánh mà không đoán","stage":"Thử thách","prompt":"Chọn các bất đẳng thức đúng.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Quy đồng hoặc dùng mô hình cùng một toàn thể để so sánh. Mẫu lớn hơn không làm phần lớn hơn.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["2/3 > 1/2","1/8 > 1/4","3/5 = 6/10","3/4 < 1/2"],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["math.transfer"]},{"id":"science-launch","topic_id":"science","position":0,"content_version":1,"title":"Cú phóng qua sông","stage":"Khám phá","prompt":"Xoay nòng pháo rồi phóng bóng đến cờ cách 10 m. Vận tốc cố định 10 m/s; g = 10 m/s².","hint_levels":["Tầm xa R = 10 × sin(2 × góc). Góc nào làm sin đạt 1?"],"explanation":"Ở 45°, tầm xa đạt tối đa 10 m trên mặt đất ngang, khi bỏ qua sức cản.","mechanism":"launchAngle","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"angle":20,"launched":false},"skill_ids":[]},{"id":"science-motion","topic_id":"science","position":1,"content_version":1,"title":"Đạo diễn hành trình","stage":"Khám phá","prompt":"Lập hành trình: đi nhanh 2 giây, nghỉ 2 giây, rồi đi chậm 2 giây. Kéo các thẻ vào đường thời gian.","hint_levels":["Đi nhanh: 2 m/s; nghỉ: 0 m/s; đi chậm: 1 m/s."],"explanation":"Quãng đường là 2×2 + 0×2 + 1×2 = 6 m.","mechanism":"motionTimeline","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"segments":[-1,-1,-1]},"skill_ids":[]},{"id":"science-lever","topic_id":"science","position":2,"content_version":1,"title":"Cân bằng mômen","stage":"Khám phá","prompt":"Bên trái: 3 kg cách trục 2 m. Đặt quả nặng 2 kg ở bên phải để cân bằng.","hint_levels":["So sánh khối lượng × khoảng cách ở hai bên."],"explanation":"3 × 2 = 2 × 3. Quả 2 kg phải cách trục 3 m.","mechanism":"leverTorque","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"position":0},"skill_ids":[]},{"id":"science-distance","topic_id":"science","position":3,"content_version":1,"title":"Cùng đích, khác hành trình","stage":"Thử thách","prompt":"Đi đúng 8 m và kết thúc bằng 2 giây nghỉ. Mỗi ô dài 2 giây; đi chậm 1 m/s, đi nhanh 2 m/s. Ghép thẻ rồi đọc đường đi.","hint_levels":["Quãng đường mỗi ô = tốc độ × 2. Thời gian nghỉ vẫn trôi, nhưng quãng đường không tăng."],"explanation":"Tổng quãng đường bằng tổng diện tích dưới từng đoạn tốc độ. Cùng một quãng đường có thể có nhiều lịch trình; các điều kiện phụ quyết định lịch trình phù hợp.","mechanism":"motionTimeline","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"segments":[-1,-1,-1]},"skill_ids":[]},{"id":"science-return","topic_id":"science","position":4,"content_version":1,"title":"Chậm trước, nhanh sau","stage":"Thử thách","prompt":"Đi đúng 6 m, bắt đầu đi chậm và kết thúc đi nhanh. Mỗi ô dài 2 giây; đi chậm 1 m/s, đi nhanh 2 m/s. Ghép thẻ rồi đọc đường đi.","hint_levels":["Quãng đường mỗi ô = tốc độ × 2. Thời gian nghỉ vẫn trôi, nhưng quãng đường không tăng."],"explanation":"Tổng quãng đường bằng tổng diện tích dưới từng đoạn tốc độ. Cùng một quãng đường có thể có nhiều lịch trình; các điều kiện phụ quyết định lịch trình phù hợp.","mechanism":"motionTimeline","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"segments":[-1,-1,-1]},"skill_ids":[]},{"id":"science-fair-test","topic_id":"science","position":5,"content_version":1,"title":"Thiết kế một phép thử","stage":"Vận dụng","prompt":"Sắp xếp quy trình thử tác động của lực lên xe mô hình.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Kiểm soát yếu tố và lặp lại giúp phân biệt tác động của lực với nhiễu đo.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Đo và lặp lại.","Đặt câu hỏi.","Giữ xe, mặt đường như nhau; thay lực.","So sánh kết quả."],"target":[1,2,0,3]},"initial_state":{"values":[0,1,2,3]},"skill_ids":["science.transfer"]},{"id":"science-motion-model","topic_id":"science","position":6,"content_version":1,"title":"Thời gian và quãng đường","stage":"Thử thách","prompt":"Trong mô hình chuyển động đều, mỗi đơn vị tốc độ là 1 m/s và mỗi đơn vị thời gian là 1 s. Mô hình giản lược: kết quả = Tốc độ × Thời gian. Mỗi tham số từ 0 đến 3. Tạo kết quả 9, dự đoán rồi chạy thử.","hint_levels":["Đổi một yếu tố mỗi lần để nhìn rõ tác động. Ghi nhớ giới hạn 0–3."],"explanation":"3 m/s × 3 s = 9 m. Mô hình giả định tốc độ không đổi; gia tốc cần mô hình khác.","mechanism":"causalExperiment","mechanism_version":1,"evaluator_version":2,"config":{"axes":["Tốc độ","Thời gian"],"goal":9},"initial_state":{"x":0,"y":0,"prediction":-1,"observed":[],"trials":[]},"skill_ids":["science.transfer"]},{"id":"data-sort","topic_id":"data","position":0,"content_version":1,"title":"Đường chân trời","stage":"Khám phá","prompt":"Kéo các cột để sắp từ thấp đến cao, từ trái qua phải.","hint_levels":["Mỗi lần thả sẽ đổi chỗ hai cột."],"explanation":"Thứ tự tăng dần là 1, 2, 3, 4. Việc sắp xếp giúp nhìn ra phân bố dữ liệu.","mechanism":"sortBars","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"order":[3,1,4,2]},"skill_ids":[]},{"id":"data-bins","topic_id":"data","position":1,"content_version":1,"title":"Bưu điện dữ liệu","stage":"Khám phá","prompt":"Đưa các số 1, 2, 4, 5, 7, 8 vào đúng khoảng của biểu đồ.","hint_levels":["Khoảng đầu chứa 0–2, khoảng giữa chứa 3–5, khoảng cuối chứa 6–8."],"explanation":"Mỗi khoảng có 2 điểm. Tổng tần số là 6, bằng số dữ liệu ban đầu.","mechanism":"histogramBins","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"bins":[-1,-1,-1,-1,-1,-1]},"skill_ids":[]},{"id":"data-mean","topic_id":"data","position":2,"content_version":1,"title":"San bằng thành phố","stage":"Khám phá","prompt":"Chuyển từng tầng giữa các tòa nhà để cả ba cao bằng nhau. Không thêm hoặc bớt tầng.","hint_levels":["Tổng là 12 tầng. Chia đều cho 3 tòa nhà."],"explanation":"Trung bình của 2, 4, 6 là (2 + 4 + 6)/3 = 4. Mọi tòa nhà cùng cao 4 tầng.","mechanism":"redistributeMean","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"heights":[2,4,6]},"skill_ids":[]},{"id":"data-outlier","topic_id":"data","position":3,"content_version":1,"title":"San đều sau một ngoại lệ","stage":"Thử thách","prompt":"Làm ba tòa cao bằng nhau. Chuyển tầng giữa ba tòa; không được thêm hay bỏ tầng.","hint_levels":["Tổng số tầng được bảo toàn. Dùng tổng và quan hệ giữa các tòa để tìm mô hình phù hợp."],"explanation":"Tổng 12 tầng không đổi sau mỗi lần chuyển. Mô hình 4 – 4 – 4 thỏa đồng thời tổng và các quan hệ đề bài.","mechanism":"redistributeMean","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"heights":[1,2,9]},"skill_ids":[]},{"id":"data-distribution","topic_id":"data","position":4,"content_version":1,"title":"Cùng trung bình, khác phân bố","stage":"Thử thách","prompt":"Giữ trung bình 4 tầng; tòa giữa cao 4 tầng, tòa phải gấp ba tòa trái. Chuyển tầng giữa ba tòa; không được thêm hay bỏ tầng.","hint_levels":["Tổng số tầng được bảo toàn. Dùng tổng và quan hệ giữa các tòa để tìm mô hình phù hợp."],"explanation":"Tổng 12 tầng không đổi sau mỗi lần chuyển. Mô hình 2 – 4 – 6 thỏa đồng thời tổng và các quan hệ đề bài.","mechanism":"redistributeMean","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"heights":[4,4,4]},"skill_ids":[]},{"id":"data-median-outlier","topic_id":"data","position":5,"content_version":1,"title":"Khi một điểm đi xa","stage":"Thử thách","prompt":"Bốn điểm cố định là 1, 2, 3, 4. Kéo điểm cuối để trung bình lớn hơn trung vị ít nhất 1 đơn vị.","hint_levels":["Trung vị là điểm thứ ba sau sắp xếp. Quan sát xem điểm cuối ảnh hưởng đến tổng như thế nào."],"explanation":"Điểm cuối từ 10 trở lên làm trung bình ít nhất bằng 4, trong khi trung vị vẫn là 3. Một ngoại lệ có thể kéo trung bình đi xa.","mechanism":"outlierExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"outlier":5},"skill_ids":[]},{"id":"data-statistics","topic_id":"data","position":6,"content_version":1,"title":"Chọn đại lượng phù hợp","stage":"Vận dụng","prompt":"Ghép mô tả với đại lượng.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Ba đại lượng mô tả các đặc điểm khác nhau của dữ liệu.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Tổng chia số giá trị","Giá trị giữa sau khi sắp xếp","Giá trị xuất hiện nhiều nhất"],"choices":["Trung vị","Mốt","Trung bình"],"target":[2,0,1]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["data.transfer"]},{"id":"data-bias","topic_id":"data","position":7,"content_version":1,"title":"Một khảo sát có đại diện?","stage":"Thử thách","prompt":"Muốn biết cách toàn trường đi học. Chọn biện pháp giảm thiên lệch.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Phạm vi lấy mẫu và cách thu thập quyết định kết luận có áp dụng cho toàn trường hay không.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Lấy mẫu ở nhiều khối lớp.","Chỉ hỏi câu lạc bộ xe đạp.","Nêu rõ cách chọn mẫu và số người trả lời.","Bỏ câu trả lời không hợp dự đoán."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["data.transfer"]},{"id":"geometry-rectangle","topic_id":"geometry","position":0,"content_version":1,"title":"Kéo ra diện tích","stage":"Khám phá","prompt":"Di chuyển bốn đỉnh để tạo hình chữ nhật có diện tích 6 ô vuông.","hint_levels":["Thử một cạnh dài 3 ô và một cạnh dài 2 ô."],"explanation":"Diện tích hình chữ nhật bằng chiều dài nhân chiều rộng: 3 × 2 = 6.","mechanism":"polygonVertices","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"points":[[0,0],[4,0],[4,4],[0,4]]},"skill_ids":[]},{"id":"geometry-mirror","topic_id":"geometry","position":1,"content_version":1,"title":"Xưởng đối xứng","stage":"Khám phá","prompt":"Chạm các ô bên phải để phản chiếu hình xanh qua trục giữa.","hint_levels":["Mỗi ô ảnh cách trục một khoảng bằng ô gốc."],"explanation":"Phép đối xứng giữ nguyên hàng và đảo vị trí cột qua trục.","mechanism":"symmetryMirror","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"cells":[]},"skill_ids":[]},{"id":"geometry-tangram","topic_id":"geometry","position":2,"content_version":1,"title":"Hai mảnh thành vuông","stage":"Khám phá","prompt":"Xoay hai tam giác, rồi kéo từng mảnh vào khung để ghép thành hình vuông.","hint_levels":["Hai cạnh huyền phải trùng nhau, hai góc vuông nằm ở hai góc đối diện."],"explanation":"Hai tam giác vuông bằng nhau ghép dọc cạnh huyền tạo thành hình vuông.","mechanism":"tangramRotate","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"turns":[1,1],"placed":[false,false]},"skill_ids":[]},{"id":"geometry-fence","topic_id":"geometry","position":3,"content_version":1,"title":"Một mảnh vườn, hai điều kiện","stage":"Thử thách","prompt":"Kéo bốn đỉnh thành hình chữ nhật có diện tích 8 ô vuông và chu vi 12 đơn vị. Mỗi khoảng lưới dài 1 đơn vị.","hint_levels":["Tìm hai cạnh vừa có tích bằng 8, vừa có tổng bằng 6. Không chỉ kiểm tra diện tích."],"explanation":"Diện tích ràng buộc tích hai cạnh; chu vi ràng buộc tổng hai cạnh. Một mô hình phải đáp ứng cả hai điều kiện.","mechanism":"polygonVertices","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"points":[[0,0],[4,0],[4,4],[0,4]]},"skill_ids":[]},{"id":"geometry-square","topic_id":"geometry","position":4,"content_version":1,"title":"Khi hình vuông xuất hiện","stage":"Thử thách","prompt":"Kéo bốn đỉnh thành hình chữ nhật có diện tích 9 ô vuông và chu vi 12 đơn vị. Mỗi khoảng lưới dài 1 đơn vị.","hint_levels":["Tìm hai cạnh vừa có tích bằng 9, vừa có tổng bằng 6. Không chỉ kiểm tra diện tích."],"explanation":"Diện tích ràng buộc tích hai cạnh; chu vi ràng buộc tổng hai cạnh. Một mô hình phải đáp ứng cả hai điều kiện.","mechanism":"polygonVertices","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"points":[[0,0],[4,0],[4,4],[0,4]]},"skill_ids":[]},{"id":"geometry-solid-volume","topic_id":"geometry","position":5,"content_version":1,"title":"Xưởng khối không gian","stage":"Khám phá 3D","prompt":"Tạo khối hộp có thể tích 12 đơn vị khối và diện tích bề mặt 32 đơn vị vuông. Xoay khối để quan sát các mặt.","hint_levels":["Thể tích là dài × cao × sâu. Thử ba kích thước có tích bằng 12 rồi so sánh tổng diện tích sáu mặt."],"explanation":"Khối có các cạnh 2, 2, 3 thỏa V = 12 và S = 2 × (4 + 6 + 6) = 32. Đổi hướng khối không đổi hai đại lượng này.","mechanism":"solidExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"width":2,"height":2,"depth":2},"skill_ids":[]},{"id":"geometry-measures","topic_id":"geometry","position":6,"content_version":1,"title":"Đơn vị nói điều gì?","stage":"Vận dụng","prompt":"Ghép phép đo với loại đơn vị.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Độ dài một chiều, diện tích hai chiều và thể tích ba chiều cần đơn vị khác nhau.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Độ dài cạnh","Diện tích mặt","Thể tích khối"],"choices":["cm³","cm","cm²"],"target":[1,2,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["geometry.transfer"]},{"id":"geometry-area-lab","topic_id":"geometry","position":7,"content_version":1,"title":"Thiết kế diện tích","stage":"Thử thách","prompt":"Dựng hình chữ nhật bằng hai cạnh nguyên, mỗi cạnh tối đa 3 đơn vị. Mô hình giản lược: kết quả = Chiều dài × Chiều rộng. Mỗi tham số từ 0 đến 3. Tạo kết quả 6, dự đoán rồi chạy thử.","hint_levels":["Đổi một yếu tố mỗi lần để nhìn rõ tác động. Ghi nhớ giới hạn 0–3."],"explanation":"Hình 2 × 3 và 3 × 2 cùng có diện tích 6; đổi hướng không đổi diện tích.","mechanism":"causalExperiment","mechanism_version":1,"evaluator_version":2,"config":{"axes":["Chiều dài","Chiều rộng"],"goal":6},"initial_state":{"x":0,"y":0,"prediction":-1,"observed":[],"trials":[]},"skill_ids":["geometry.transfer"]},{"id":"coding-route","topic_id":"coding","position":0,"content_version":1,"title":"Dẫn robot về nhà","stage":"Khám phá","prompt":"Vuốt trên bản đồ hoặc thêm lệnh để dẫn robot từ góc trái trên tới ngôi sao. Tránh ô đá ở giữa.","hint_levels":["Đi theo mép trên rồi rẽ xuống. Bạn có thể xóa lệnh để thử lại."],"explanation":"Một thuật toán là chuỗi thao tác rõ ràng; thứ tự lệnh quyết định đường đi.","mechanism":"robotRoute","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"commands":[]},"skill_ids":[]},{"id":"coding-loop","topic_id":"coding","position":1,"content_version":1,"title":"Cầu thang vòng lặp","stage":"Khám phá","prompt":"Lắp hai lệnh và đặt số lần lặp để robot đi đúng cầu thang: sang phải rồi xuống, ba lần.","hint_levels":["Khối lặp giúp dùng hai lệnh để tạo ra sáu bước."],"explanation":"Lặp [phải, xuống] ba lần tạo đường cầu thang tới ô (3, 3).","mechanism":"loopBuilder","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"body":["D","R"],"repeat":1},"skill_ids":[]},{"id":"coding-sort","topic_id":"coding","position":2,"content_version":1,"title":"Thiết kế máy sắp xếp","stage":"Khám phá","prompt":"Lắp tối đa 6 bộ so sánh giữa các dây kề nhau, rồi chạy máy. Mạng cần sắp đúng cả 24 thứ tự đầu vào.","hint_levels":["Mỗi bộ so sánh chỉ đổi chỗ khi số trên lớn hơn số dưới. Thử chuỗi 1–2, 2–3, 3–4, rồi xử lý ba dây đầu."],"explanation":"Một mạng sắp xếp dùng cùng chuỗi bộ so sánh cho mọi đầu vào. Mỗi bộ tự đưa số nhỏ lên trên; mạng này đã vượt qua cả 24 hoán vị.","mechanism":"sortingNetwork","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"stages":[],"result":[]},"skill_ids":[]},{"id":"coding-shortest","topic_id":"coding","position":3,"content_version":1,"title":"Tiết kiệm từng lệnh","stage":"Thử thách","prompt":"Dẫn robot tới sao bằng tối đa 6 lệnh, tránh đá và mép bản đồ.","hint_levels":["Mỗi bước chỉ thay đổi một tọa độ. Quan sát đường vẽ và loại các bước vòng lại không cần thiết."],"explanation":"Thuật toán tốt vừa đi đúng, vừa tuân thủ giới hạn tài nguyên. Đường đi của bạn vượt qua đá, đến đích và đáp ứng giới hạn 6 lệnh.","mechanism":"robotRoute","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"commands":[]},"skill_ids":[]},{"id":"coding-checkpoint","topic_id":"coding","position":4,"content_version":1,"title":"Ghé trạm trước khi về","stage":"Thử thách","prompt":"Dẫn robot tới sao bằng tối đa 6 lệnh, tránh đá và mép bản đồ. Trước khi tới đích, phải qua cột 1, hàng 3 (đếm từ góc trái trên).","hint_levels":["Mỗi bước chỉ thay đổi một tọa độ. Quan sát đường vẽ và loại các bước vòng lại không cần thiết."],"explanation":"Thuật toán tốt vừa đi đúng, vừa tuân thủ giới hạn tài nguyên. Đường đi của bạn vượt qua đá, đến đích và đáp ứng giới hạn 6 lệnh.","mechanism":"robotRoute","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"commands":[]},"skill_ids":[]},{"id":"coding-variable-trace","topic_id":"coding","position":5,"content_version":1,"title":"Theo dõi biến từng dòng","stage":"Nền tảng Python","prompt":"Đoạn Python in ra số nào?","hint_levels":["Lập bảng x: 3 → 5, rồi mới tính y."],"explanation":"Sau dòng hai, x = 5. Dòng ba gán y = 10 nên print(y) in 10.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Phép gán lưu giá trị vào tên biến. Biểu thức ở vế phải được tính trước khi cập nhật biến ở vế trái. Hãy ghi lại giá trị sau mỗi dòng để đọc mã chính xác.","choices":["6","10","8"],"reasons":["x vẫn giữ 3 sau mọi phép gán.","Python thực hiện các dòng theo thứ tự ngược.","x được cập nhật thành 5 trước khi tính y = 5 * 2."],"source":"Python Software Foundation, Python 3 Tutorial: Control Flow / Data Structures","code":"x = 3\nx = x + 2\ny = x * 2\nprint(y)"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["coding-variable-trace"]},{"id":"coding-branch-boundary","topic_id":"coding","position":6,"content_version":1,"title":"Điều kiện ở ranh giới","stage":"Vận dụng Python","prompt":"Khi score = 5, chương trình in gì?","hint_levels":["Phân biệt > với >=."],"explanation":"Dấu bằng nằm trong >=. Điều kiện đúng tại 5, vì vậy chương trình in “Đạt” và bỏ qua else.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Toán tử >= bao gồm giá trị bằng ngưỡng. Trong if/else, chỉ nhánh phù hợp điều kiện được thực hiện. Giá trị đúng bằng ngưỡng là một ca kiểm thử quan trọng.","choices":["Đạt","Chưa đạt","In cả hai dòng"],"reasons":[">= chỉ nhận các số lớn hơn 5.","5 >= 5 đúng nên chỉ thực hiện nhánh if.","else luôn chạy sau if."],"source":"Python Software Foundation, Python 3 Tutorial: Control Flow / Data Structures","code":"score = 5\nif score >= 5:\n    print(\"Đạt\")\nelse:\n    print(\"Chưa đạt\")"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["coding-branch-boundary"]},{"id":"coding-loop-accumulator","topic_id":"coding","position":7,"content_version":1,"title":"Vòng lặp và biến tích lũy","stage":"Vận dụng Python","prompt":"Giá trị total cuối cùng là bao nhiêu?","hint_levels":["Liệt kê các giá trị n trước, rồi cộng lần lượt."],"explanation":"Ba lần cập nhật là 0 + 1 = 1, 1 + 2 = 3, 3 + 3 = 6. Không có vòng n = 4.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"range(1, 4) tạo các số 1, 2, 3; cận cuối 4 không được lấy. Biến tích lũy giữ kết quả qua các vòng lặp.","choices":["10","4","6"],"reasons":["total lần lượt là 1, 3, 6 khi n là 1, 2, 3.","range luôn bao gồm cận cuối.","Mỗi vòng lặp đặt total về 0."],"source":"Python Software Foundation, Python 3 Tutorial: Control Flow / Data Structures","code":"total = 0\nfor n in range(1, 4):\n    total = total + n\nprint(total)"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["coding-loop-accumulator"]},{"id":"coding-list-alias","topic_id":"coding","position":8,"content_version":1,"title":"Hai tên, một danh sách","stage":"Phân tích Python","prompt":"Sau đoạn mã, a có giá trị nào?","hint_levels":["Vẽ hai mũi tên a và b tới cùng một hộp danh sách."],"explanation":"append thay đổi chính danh sách dùng chung, vì vậy a là [1, 2, 3]. Với ví dụ các số này, b = a.copy() sẽ tách danh sách trước khi append.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Gán b = a với danh sách không tạo bản sao. Hai tên cùng tham chiếu một đối tượng. a.copy() có thể tạo bản sao nông khi cần một danh sách khác.","choices":["[1, 2]","[1, 2, 3]","[3]"],"reasons":["b = a tạo bản sao độc lập.","append thay thế toàn bộ danh sách.","a và b trỏ tới cùng danh sách nên thay đổi qua b cũng thấy qua a."],"source":"Python Software Foundation, Python 3 Tutorial: Control Flow / Data Structures","code":"a = [1, 2]\nb = a\nb.append(3)\nprint(a)"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["coding-list-alias"]},{"id":"coding-function-return","topic_id":"coding","position":9,"content_version":1,"title":"Giá trị trả về của hàm","stage":"Phân tích Python","prompt":"Chương trình in số nào?","hint_levels":["Thay lời gọi double(4) bằng giá trị nó trả về."],"explanation":"double(4) trả 8. result = 8 + 1 = 9; chỉ print(result) tạo đầu ra trong đoạn mã này.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"return gửi kết quả từ hàm về nơi gọi. Biến tham số nhận đối số cho lần gọi đó. Phân biệt việc tính giá trị với việc in giá trị ra màn hình.","choices":["9","8","5"],"reasons":["Hàm trả 8 cho nơi gọi; biểu thức bên ngoài cộng thêm 1.","return tự in 8 và bỏ qua phép cộng.","Tham số n luôn bằng 2."],"source":"Python Software Foundation, Python 3 Tutorial: Control Flow / Data Structures","code":"def double(n):\n    return n * 2\n\nresult = double(4) + 1\nprint(result)"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["coding-function-return"]},{"id":"coding-test-boundaries","topic_id":"coding","position":10,"content_version":1,"title":"Chọn kiểm thử bắt lỗi","stage":"Thử thách Python","prompt":"Hàm phải trả True từ 18 tuổi. Ca nào trực tiếp phát hiện lỗi của đoạn mã?","hint_levels":["Thử giá trị đúng bằng ngưỡng được nhắc trong yêu cầu."],"explanation":"Hàm hiện trả False tại tuổi 18. Sửa điều kiện thành age >= 18 và kiểm tra lại các ca 17, 18, 19 để bao phủ ranh giới.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Kiểm thử phải đối chiếu yêu cầu. Với yêu cầu “từ 18 tuổi”, các giá trị dưới ngưỡng, đúng ngưỡng và trên ngưỡng giúp phát hiện sai lệch ở ranh giới.","choices":["age = 25, mong đợi True","age = 17, mong đợi False","age = 18, mong đợi True"],"reasons":["Mọi giá trị trên 18 đều gây lỗi.","18 > 18 là False, trái yêu cầu bao gồm tuổi 18.","Không thể kiểm thử hàm có tham số."],"source":"Python Software Foundation, Python 3 Tutorial: Control Flow / Data Structures","code":"def eligible(age):\n    return age > 18"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["coding-test-boundaries"]},{"id":"coding-debug-cycle","topic_id":"coding","position":11,"content_version":1,"title":"Gỡ lỗi có phương pháp","stage":"Vận dụng","prompt":"Sắp xếp quy trình gỡ lỗi thay vì sửa ngẫu nhiên.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Tái hiện → xác định nguyên nhân → sửa → kiểm tra hồi quy giúp tránh tạo lỗi mới.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Sửa nguyên nhân đã xác định.","Tái hiện lỗi với đầu vào nhỏ.","Chạy lại ca lỗi và ca bình thường.","Theo dấu bước sai đầu tiên."],"target":[1,3,0,2]},"initial_state":{"values":[0,1,2,3]},"skill_ids":["coding.transfer"]},{"id":"coding-tests","topic_id":"coding","position":12,"content_version":1,"title":"Kiểm tra ranh giới","stage":"Thử thách","prompt":"Hàm nhận tuổi nguyên từ 6 đến 18. Chọn các cặp đầu vào kiểm tra hai ranh giới trong/ngoài.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"5/6 kiểm tra cận dưới; 18/19 kiểm tra cận trên. Ca giữa miền chưa kiểm tra lỗi lệch một đơn vị.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["5 và 6","10 và 11","18 và 19","12 và 13"],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["coding.transfer"]},{"id":"circuits-wire","topic_id":"circuits","position":0,"content_version":1,"title":"Ánh sáng đầu tiên","stage":"Khám phá","prompt":"Đèn và nguồn đã gắn sẵn. Kéo hai dây để nối cực dương nguồn tới đầu vào đèn, rồi nối đầu ra đèn về cực âm.","hint_levels":["Cần dây 1–2 và dây 3–4. Đừng nối trực tiếp hai cực nguồn hoặc nối tắt hai đầu đèn."],"explanation":"Dòng điện cần một đường kín từ nguồn, qua tải và trở về nguồn.","mechanism":"wireCircuit","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"edges":[]},"skill_ids":[]},{"id":"circuits-logic","topic_id":"circuits","position":1,"content_version":1,"title":"Đường điện dự phòng","stage":"Khám phá","prompt":"Nhánh A đang bảo trì: giữ A mở. Bật đèn bằng nhánh B và công tắc chính C.","hint_levels":["A và B mắc song song, cả hai cùng đi qua C."],"explanation":"Mạch sáng khi (A HOẶC B) VÀ C. Với A mở, B và C đều phải đóng.","mechanism":"switchLogic","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"switches":[false,false,false]},"skill_ids":[]},{"id":"circuits-light","topic_id":"circuits","position":2,"content_version":1,"title":"Phòng pha ánh sáng","stage":"Khám phá","prompt":"Điều chỉnh ba chùm sáng để tạo màu vàng của mẫu.","hint_levels":["Ánh sáng đỏ cộng ánh sáng lục tạo vàng; ánh sáng lam làm màu nhạt đi."],"explanation":"Pha màu cộng: đỏ + lục = vàng. Đây là ánh sáng, khác pha sơn.","mechanism":"colorMixer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"rgb":[0.0,0.0,1.0]},"skill_ids":[]},{"id":"circuits-cyan","topic_id":"circuits","position":3,"content_version":1,"title":"Trộn ra màu trời","stage":"Vận dụng","prompt":"Điều chỉnh ba nguồn sáng để khớp mẫu lục lam. Quan sát màu trộn khi tăng hoặc giảm từng nguồn.","hint_levels":["Thử bật từng cặp nguồn, rồi cả ba nguồn. Đây là pha ánh sáng cộng, không phải pha sơn."],"explanation":"Mẫu lục lam được tạo bởi mức đỏ–lục–lam 0% – 100% – 100%. Cộng các chùm sáng thay đổi cả sắc và độ sáng.","mechanism":"colorMixer","mechanism_version":1,"evaluator_version":1,"config":{"color":4278255615,"colorLabel":"Mẫu lục lam"},"initial_state":{"rgb":[0.0,0.0,0.0]},"skill_ids":[]},{"id":"circuits-white","topic_id":"circuits","position":4,"content_version":1,"title":"Từ ba màu thành trắng","stage":"Vận dụng","prompt":"Điều chỉnh ba nguồn sáng để khớp mẫu trắng. Quan sát màu trộn khi tăng hoặc giảm từng nguồn.","hint_levels":["Thử bật từng cặp nguồn, rồi cả ba nguồn. Đây là pha ánh sáng cộng, không phải pha sơn."],"explanation":"Mẫu trắng được tạo bởi mức đỏ–lục–lam 100% – 100% – 100%. Cộng các chùm sáng thay đổi cả sắc và độ sáng.","mechanism":"colorMixer","mechanism_version":1,"evaluator_version":1,"config":{"color":4294967295,"colorLabel":"Mẫu trắng"},"initial_state":{"rgb":[0.0,0.0,0.0]},"skill_ids":[]},{"id":"circuits-concepts","topic_id":"circuits","position":5,"content_version":1,"title":"Đọc mạch bằng khái niệm","stage":"Vận dụng","prompt":"Ghép đại lượng và đơn vị.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Các đại lượng có đơn vị riêng; trong mô hình điện trở thuần có thể liên hệ bằng U = I × R.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Hiệu điện thế","Cường độ dòng điện","Điện trở"],"choices":["ohm (Ω)","volt (V)","ampere (A)"],"target":[1,2,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["circuits.transfer"]},{"id":"circuits-safety","topic_id":"circuits","position":6,"content_version":1,"title":"Thử nghiệm có trách nhiệm","stage":"Thử thách","prompt":"Chọn cách khám phá phù hợp cho người học.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Mô phỏng giúp thử không gây nguy hiểm. Không dùng điện lưới hay cố tình nối tắt nguồn.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Dùng mô phỏng trong app.","Chọc vật vào ổ điện để thử dẫn điện.","Chỉ dùng bộ học điện áp thấp với người lớn hướng dẫn.","Nối tắt pin để xem có nóng không."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["circuits.transfer"]},{"id":"probability-bag","topic_id":"probability","position":0,"content_version":1,"title":"Túi bí mật","stage":"Khám phá","prompt":"Thả đủ 6 viên vào túi để xác suất rút một viên xanh là 1/3.","hint_levels":["Trong 6 viên, cần 2 viên xanh. Các viên còn lại màu đỏ."],"explanation":"Có 2 kết quả xanh trên 6 viên đồng khả năng: 2/6 = 1/3.","mechanism":"probabilityBag","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"balls":[]},"skill_ids":[]},{"id":"probability-space","topic_id":"probability","position":1,"content_version":1,"title":"Bản đồ hai đồng xu","stage":"Khám phá","prompt":"Ghép từng cặp mặt xu vào bảng để liệt kê đủ các kết quả khi tung hai đồng xu có thứ tự.","hint_levels":["SN khác NS vì đồng thứ nhất và đồng thứ hai được phân biệt."],"explanation":"Không gian mẫu gồm SS, SN, NS, NN. Bốn kết quả có xác suất bằng nhau với xu cân đối.","mechanism":"sampleSpace","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"outcomes":[]},"skill_ids":[]},{"id":"probability-spinner","topic_id":"probability","position":2,"content_version":1,"title":"Thiết kế vòng quay","stage":"Khám phá","prompt":"Kéo tay nắm để phần màu xanh chiếm 3/8 vòng quay.","hint_levels":["Vòng quay được chia thành 8 cung bằng nhau; cần 3 cung xanh."],"explanation":"Xác suất trúng màu xanh bằng phần góc xanh trên cả vòng: 3 × 45° / 360° = 3/8.","mechanism":"probabilitySpinner","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"sectors":1},"skill_ids":[]},{"id":"probability-fair","topic_id":"probability","position":3,"content_version":1,"title":"Thiết kế một túi công bằng","stage":"Thử thách","prompt":"Hai màu phải có cơ hội xuất hiện bằng nhau. Dựng túi gồm đúng 8 viên bằng cách thêm hoặc lấy bi ra.","hint_levels":["Hai màu chia sẻ cùng một tổng. Chuyển điều kiện đề bài thành số viên của từng màu rồi kiểm tra lại cả túi."],"explanation":"Có 4 viên xanh và 4 viên đỏ, nên P(xanh) = 4/8. Cơ hội thay đổi khi tỉ lệ các màu thay đổi.","mechanism":"probabilityBag","mechanism_version":1,"evaluator_version":1,"config":{"capacity":8},"initial_state":{"balls":[]},"skill_ids":[]},{"id":"probability-odds","topic_id":"probability","position":4,"content_version":1,"title":"Cơ hội gấp ba","stage":"Thử thách","prompt":"Cơ hội rút xanh phải gấp ba cơ hội rút đỏ. Dựng túi gồm đúng 8 viên bằng cách thêm hoặc lấy bi ra.","hint_levels":["Hai màu chia sẻ cùng một tổng. Chuyển điều kiện đề bài thành số viên của từng màu rồi kiểm tra lại cả túi."],"explanation":"Có 6 viên xanh và 2 viên đỏ, nên P(xanh) = 6/8. Cơ hội thay đổi khi tỉ lệ các màu thay đổi.","mechanism":"probabilityBag","mechanism_version":1,"evaluator_version":1,"config":{"capacity":8},"initial_state":{"balls":[]},"skill_ids":[]},{"id":"probability-language","topic_id":"probability","position":5,"content_version":1,"title":"Từ cơ hội đến con số","stage":"Vận dụng","prompt":"Ghép xác suất với mô tả trong mô hình.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Xác suất từ 0 đến 1; 1/2 cần giả định các kết quả liên quan đồng khả năng.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["0","1/2","1"],"choices":["Chắc chắn","Không thể","Hai kết quả đối xứng, đồng khả năng"],"target":[1,2,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["probability.transfer"]},{"id":"probability-independence","topic_id":"probability","position":6,"content_version":1,"title":"Đồng xu có trí nhớ không?","stage":"Thử thách","prompt":"Đồng xu cân đối, các lần tung độc lập. Chọn phát biểu đúng sau ba lần ngửa.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Độc lập nghĩa là các lần trước không buộc lần sau bù lại. Kiểm tra độ lệch cần đủ dữ liệu và mô hình thống kê.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Lần tiếp theo vẫn có xác suất ngửa 1/2.","Lần tiếp theo chắc chắn sấp.","Một chuỗi ngắn không đủ chứng minh đồng xu lệch.","Đồng xu phải bù lại các lần ngửa."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["probability.transfer"]},{"id":"algebra-isolate","topic_id":"algebra","position":0,"content_version":1,"title":"Ẩn số sau những khối","stage":"Vận dụng","prompt":"Mô hình đang biểu diễn x + 2 = 8. Giữ cân bằng và cô lập x bằng cách bỏ cùng một lượng ở hai vế.","hint_levels":["Quan sát lượng còn cộng với x. Mỗi thao tác phải giữ hai vế bằng nhau."],"explanation":"Bớt 2 ở cả hai vế bảo toàn đẳng thức: x = 6. Giá trị thay đổi, quy tắc cân bằng vẫn giữ nguyên.","mechanism":"removeBothSides","mechanism_version":1,"evaluator_version":1,"config":{"extra":2,"total":8},"initial_state":{"pairs":0},"skill_ids":[]},{"id":"algebra-transfer","topic_id":"algebra","position":1,"content_version":1,"title":"Thay số, giữ quy tắc","stage":"Vận dụng","prompt":"Mô hình đang biểu diễn x + 4 = 10. Giữ cân bằng và cô lập x bằng cách bỏ cùng một lượng ở hai vế.","hint_levels":["Quan sát lượng còn cộng với x. Mỗi thao tác phải giữ hai vế bằng nhau."],"explanation":"Bớt 4 ở cả hai vế bảo toàn đẳng thức: x = 6. Giá trị thay đổi, quy tắc cân bằng vẫn giữ nguyên.","mechanism":"removeBothSides","mechanism_version":1,"evaluator_version":1,"config":{"extra":4,"total":10},"initial_state":{"pairs":0},"skill_ids":[]},{"id":"algebra-model","topic_id":"algebra","position":2,"content_version":1,"title":"Giải bằng một thành phố","stage":"Thử thách","prompt":"Tòa giữa gấp đôi tòa trái; tòa phải gấp ba tòa trái. Tìm cả ba chiều cao. Chuyển tầng giữa ba tòa; không được thêm hay bỏ tầng.","hint_levels":["Tổng số tầng được bảo toàn. Dùng tổng và quan hệ giữa các tòa để tìm mô hình phù hợp."],"explanation":"Tổng 12 tầng không đổi sau mỗi lần chuyển. Mô hình 2 – 4 – 6 thỏa đồng thời tổng và các quan hệ đề bài.","mechanism":"redistributeMean","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"heights":[6,3,3]},"skill_ids":[]},{"id":"algebra-solid-relation","topic_id":"algebra","position":3,"content_version":1,"title":"Một khối, ba quan hệ","stage":"Vận dụng 3D","prompt":"Dựng khối hộp có thể tích 16 đơn vị khối. Chiều dài gấp đôi chiều cao; chiều sâu bằng chiều cao.","hint_levels":["Cho chiều cao và chiều sâu bằng nhau trước. Mỗi khi đổi chiều cao, chiều dài cần thay đổi thế nào?"],"explanation":"Cao = sâu = 2 và dài = 4: thể tích là 4 × 2 × 2 = 16. Mô hình phải thỏa cả thể tích lẫn quan hệ giữa các cạnh.","mechanism":"solidExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"width":2,"height":2,"depth":2},"skill_ids":[]},{"id":"algebra-solve-steps","topic_id":"algebra","position":4,"content_version":1,"title":"Giải và kiểm chứng","stage":"Vận dụng","prompt":"Sắp xếp lời giải phương trình 2x + 3 = 11.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Mỗi phép biến đổi giữ tương đương; thay lại xác nhận 2 × 4 + 3 = 11.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Chia hai vế cho 2: x = 4.","Trừ 3 ở hai vế: 2x = 8.","Thay x = 4 vào phương trình ban đầu."],"target":[1,0,2]},"initial_state":{"values":[0,1,2]},"skill_ids":["algebra.transfer"]},{"id":"algebra-functions","topic_id":"algebra","position":5,"content_version":1,"title":"Đọc quy tắc hàm số","stage":"Thử thách","prompt":"Với y = 2x + 1, ghép x với y.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Thay từng giá trị vào cùng quy tắc. Hệ số 2 mô tả mức thay đổi; 1 là giá trị tại x = 0.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["x = 0","x = 2","x = −1"],"choices":["5","−1","1"],"target":[2,0,1]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["algebra.transfer"]},{"id":"optimization-debug","topic_id":"optimization","position":0,"content_version":1,"title":"Gỡ lỗi đường đi","stage":"Thử thách","prompt":"Dẫn robot tới sao bằng tối đa 6 lệnh, tránh đá và mép bản đồ. Đường hiện tại có lỗi: dùng nút lùi để sửa.","hint_levels":["Mỗi bước chỉ thay đổi một tọa độ. Quan sát đường vẽ và loại các bước vòng lại không cần thiết."],"explanation":"Thuật toán tốt vừa đi đúng, vừa tuân thủ giới hạn tài nguyên. Đường đi của bạn vượt qua đá, đến đích và đáp ứng giới hạn 6 lệnh.","mechanism":"robotRoute","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"commands":["R","D"]},"skill_ids":[]},{"id":"optimization-network","topic_id":"optimization","position":1,"content_version":1,"title":"Sửa máy, không sửa đầu vào","stage":"Thử thách","prompt":"Máy đã có ba bộ so sánh nhưng chưa sắp đúng mọi đầu vào. Chỉnh hoặc lắp thêm, tối đa 6 bộ; chạy kiểm tra cả 24 hoán vị.","hint_levels":["Một đầu vào chạy đúng chưa chứng minh máy đúng. Tìm cặp dây còn có thể đảo thứ tự sau mỗi lượt."],"explanation":"Máy được kiểm tra trên cả 24 hoán vị, không chỉ ví dụ đang hiển thị. Chuỗi bộ so sánh dùng lại được với mọi đầu vào.","mechanism":"sortingNetwork","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"stages":[0,1,2],"result":[]},"skill_ids":[]},{"id":"optimization-budget","topic_id":"optimization","position":2,"content_version":1,"title":"Ngân sách chuyển động","stage":"Thử thách","prompt":"Đi đúng 4 m với chỉ một ô đi nhanh; hai ô còn lại phải nghỉ. Mỗi ô dài 2 giây; đi chậm 1 m/s, đi nhanh 2 m/s. Ghép thẻ rồi đọc đường đi.","hint_levels":["Quãng đường mỗi ô = tốc độ × 2. Thời gian nghỉ vẫn trôi, nhưng quãng đường không tăng."],"explanation":"Tổng quãng đường bằng tổng diện tích dưới từng đoạn tốc độ. Cùng một quãng đường có thể có nhiều lịch trình; các điều kiện phụ quyết định lịch trình phù hợp.","mechanism":"motionTimeline","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"segments":[-1,-1,-1]},"skill_ids":[]},{"id":"optimization-time","topic_id":"optimization","position":3,"content_version":1,"title":"Tối ưu với nhiều điều kiện","stage":"Thử thách","prompt":"Chia 10 lượt xử lý cho một hệ thống giả lập. Phân bổ đúng 10 đơn vị; mỗi mục phải đạt mức tối thiểu ghi bên dưới.","hint_levels":["Đáp ứng các mức tối thiểu trước, rồi phân bổ phần còn lại. Có thể có nhiều phương án đúng."],"explanation":"Phương án khả thi phải thỏa tổng và từng cận dưới; chỉ tối đa tính toán có thể làm mất độ tin cậy.","mechanism":"resourceBudget","mechanism_version":1,"evaluator_version":2,"config":{"items":["Tính toán","Kiểm tra","Dự phòng"],"minima":[5,2,1]},"initial_state":{"values":[0,0,0]},"skill_ids":["optimization.transfer"]},{"id":"optimization-greedy","topic_id":"optimization","position":4,"content_version":1,"title":"Nhanh trước mắt có luôn tốt?","stage":"Thử thách","prompt":"Chọn nhận định đúng về lựa chọn tham lam.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Tốc độ và tối ưu là hai tính chất khác nhau. Chiến lược cục bộ cần điều kiện hoặc chứng minh để đảm bảo toàn cục.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Có bài toán cần chứng minh tính đúng của chiến lược.","Chọn rẻ nhất mỗi bước luôn tối ưu mọi bài.","Một phản ví dụ đủ bác bỏ lời khẳng định luôn tối ưu.","Chạy nhanh đồng nghĩa kết quả tối ưu."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["optimization.transfer"]},{"id":"geography-globe-grid","topic_id":"geography","position":0,"content_version":1,"title":"Tìm đường trên quả địa cầu","stage":"Khám phá 3D","prompt":"Đặt điểm tại 15° Bắc, 105° Đông trên quả địa cầu. Xoay để nhìn quanh, rồi chạm bề mặt hoặc điều chỉnh tọa độ.","hint_levels":["Vĩ độ Bắc nằm phía bắc xích đạo. Kinh độ Đông được đo về phía đông từ kinh tuyến gốc 0°."],"explanation":"Vĩ độ đo vị trí Bắc–Nam; kinh độ đo vị trí Đông–Tây. Xoay quả địa cầu chỉ đổi góc nhìn, không đổi tọa độ điểm.","mechanism":"globeExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"latitude":0,"longitude":0},"skill_ids":[]},{"id":"geography-rock-layers","topic_id":"geography","position":1,"content_version":1,"title":"Đọc lịch sử trong lớp đất đá","stage":"Vận dụng 3D","prompt":"Các lớp trầm tích chưa bị đảo lộn. Sắp lớp có tuổi 10, 20 và 30 triệu năm từ trên xuống dưới, theo thứ tự hình thành.","hint_levels":["Trong chuỗi trầm tích không bị đảo lộn, lớp bên dưới hình thành trước lớp phủ lên trên."],"explanation":"Từ trên xuống: 10, 20, 30 triệu năm. Mô hình giả định các lớp lắng đọng liên tiếp, chưa bị biến dạng hoặc đảo lộn.","mechanism":"strataExplorer","mechanism_version":1,"evaluator_version":1,"config":{},"initial_state":{"layers":[30,10,20]},"skill_ids":[]},{"id":"geography-coordinates","topic_id":"geography","position":2,"content_version":1,"title":"Ngôn ngữ bản đồ","stage":"Vận dụng","prompt":"Ghép tọa độ hoặc hướng với mô tả.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Vĩ độ đo vị trí bắc–nam, kinh độ đo đông–tây theo quy ước.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Vĩ độ 0°","Kinh độ 0°","Vĩ độ 90°B"],"choices":["Cực Bắc","Xích đạo","Kinh tuyến gốc"],"target":[1,2,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["geography.transfer"]},{"id":"geography-map","topic_id":"geography","position":3,"content_version":1,"title":"Đọc bản đồ có phê phán","stage":"Thử thách","prompt":"Chọn điều cần kiểm tra trước khi so sánh hai bản đồ.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Phép chiếu tạo đánh đổi hình học; dữ liệu và thời điểm cũng quyết định cách diễn giải.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Tỷ lệ và phép chiếu.","Màu đẹp hơn nghĩa là đúng hơn.","Ngày và nguồn dữ liệu.","Mọi phép chiếu đều bảo toàn cả diện tích lẫn góc."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["geography.transfer"]},{"id":"marxism-sources","topic_id":"marxism","position":0,"content_version":1,"title":"Ba nguồn gốc, ba bộ phận","stage":"Nền tảng","prompt":"Một nhóm đang đọc về hàng hóa, lao động và giá trị thặng dư. Nhóm đang tìm hiểu bộ phận nào?","hint_levels":["Xem đối tượng được nghiên cứu, thay vì chỉ nhìn tên tác giả."],"explanation":"Hàng hóa, lao động và giá trị thặng dư thuộc kinh tế chính trị Mác. Ba bộ phận có liên hệ nhưng không đồng nhất đối tượng nghiên cứu.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Trong bài viết năm 1913, Lênin trình bày ba nguồn gốc: triết học Đức, kinh tế chính trị Anh và chủ nghĩa xã hội Pháp. Ba bộ phận được bàn đến là triết học, kinh tế chính trị và chủ nghĩa xã hội khoa học. Bài học tìm hiểu nội dung học thuyết trong bối cảnh lịch sử.","choices":["Triết học","Kinh tế chính trị","Lịch sử hội họa"],"reasons":["Đối tượng là các quan hệ kinh tế trong sản xuất và trao đổi.","Mọi văn bản của Mác đều chỉ thuộc triết học.","Tên tác giả quyết định môn học, không cần xem nội dung."],"source":"V. I. Lenin, Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác (1913) · Marxists Internet Archive"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["marxism-sources"]},{"id":"marxism-material-conditions","topic_id":"marxism","position":1,"content_version":1,"title":"Điều kiện vật chất và ý thức","stage":"Nền tảng","prompt":"Máy móc mới làm thay đổi cách một xưởng phân công lao động. Câu hỏi nào phù hợp với cách tiếp cận duy vật lịch sử?","hint_levels":["Phân biệt khảo sát điều kiện vật chất với kết luận máy móc rằng công nghệ quyết định tất cả."],"explanation":"Câu hỏi về công cụ và quan hệ lao động mở ra việc khảo sát cụ thể. Không thể từ một ví dụ kết luận công nghệ là nguyên nhân duy nhất của mọi biến đổi xã hội.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Trong Lời tựa năm 1859, Mác nhấn mạnh quan hệ giữa đời sống vật chất, quan hệ sản xuất và đời sống tinh thần. Khi vận dụng, cần chỉ ra điều kiện và cơ chế cụ thể, thay vì giải thích mọi biến đổi bằng mong muốn cá nhân.","choices":["Ai đã mong muốn thay đổi nhất?","Có thể bỏ qua điều kiện làm việc không?","Công cụ và quan hệ lao động thay đổi như thế nào?"],"reasons":["Ý muốn cá nhân luôn là nguyên nhân duy nhất.","Cần khảo sát cơ sở vật chất và các quan hệ xã hội cụ thể.","Công nghệ tự quyết định mọi kết quả, không cần con người."],"source":"Karl Marx, Lời tựa Góp phần phê phán khoa kinh tế chính trị (1859) · Marxists Internet Archive"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["marxism-material-conditions"]},{"id":"marxism-relations","topic_id":"marxism","position":2,"content_version":1,"title":"Lực lượng và quan hệ sản xuất","stage":"Vận dụng","prompt":"Trong một xưởng, chi tiết nào mô tả quan hệ sản xuất rõ nhất?","hint_levels":["Tách thuộc tính kỹ thuật của công cụ khỏi quan hệ xã hội giữa những người sử dụng chúng."],"explanation":"Quyền sở hữu và tổ chức quan hệ lao động là khía cạnh xã hội của sản xuất. Công suất và độ bền mô tả đặc điểm kỹ thuật của tư liệu sản xuất.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Lực lượng sản xuất liên quan đến người lao động, năng lực và tư liệu sản xuất. Quan hệ sản xuất là những quan hệ xã hội trong quá trình sản xuất; không nên đồng nhất chúng với bản thân máy móc.","choices":["Quyền sở hữu xưởng và cách tổ chức quan hệ lao động.","Công suất động cơ.","Độ bền của lưỡi cắt."],"reasons":["Mọi thứ có thể đo được đều là quan hệ sản xuất.","Quan hệ sản xuất chỉ là tình bạn giữa đồng nghiệp.","Đây là quan hệ giữa người với người trong sản xuất."],"source":"Karl Marx, Lời tựa Góp phần phê phán khoa kinh tế chính trị (1859) · Marxists Internet Archive"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["marxism-relations"]},{"id":"marxism-surplus","topic_id":"marxism","position":3,"content_version":1,"title":"Đọc mô hình giá trị thặng dư","stage":"Vận dụng","prompt":"Mô hình giả định giá trị mới là 120 đơn vị, v = 80. Giá trị thặng dư m và tỷ suất m/v là bao nhiêu?","hint_levels":["Trước tiên tách giá trị mới thành v + m. Mẫu số của tỷ suất là v."],"explanation":"m = 120 − 80 = 40 và m/v = 40/80 = 50%. Kết quả chỉ thuộc mô hình giả định; không dùng trực tiếp để suy ra lợi nhuận thực tế của một doanh nghiệp.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Trong mô hình kinh tế của Mác, giá trị mới do lao động tạo ra được phân thành phần bù giá trị sức lao động (v) và giá trị thặng dư (m). Tỷ suất giá trị thặng dư là m/v. Không đồng nhất giá trị mới với doanh thu hay m với lợi nhuận kế toán.","choices":["m = 40; tỷ suất 50%.","m = 120; tỷ suất 150%.","m = 40; tỷ suất 33,3%."],"reasons":["Lấy 40 chia tổng giá trị mới 120.","m = 120 − 80; lấy m chia v = 80.","Doanh thu luôn bằng giá trị thặng dư."],"source":"V. I. Lenin, Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác (1913) · Marxists Internet Archive"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["marxism-surplus"]},{"id":"marxism-social-change","topic_id":"marxism","position":4,"content_version":1,"title":"Đọc biến đổi xã hội trong bối cảnh","stage":"Phân tích","prompt":"Một bài viết khẳng định: “Chỉ cần đổi máy móc là mọi quan hệ xã hội lập tức thay đổi.” Cách đánh giá nào thận trọng nhất?","hint_levels":["Phân biệt một mối liên hệ cần nghiên cứu với một kết luận tuyệt đối."],"explanation":"Khảo sát quan hệ lao động, thể chế và quá trình biến đổi giúp tránh giải thích đơn tuyến. Vai trò của kỹ thuật cần được phân tích cùng các điều kiện xã hội cụ thể.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Mác phân tích mối liên hệ và xung đột giữa lực lượng sản xuất và quan hệ sản xuất. Một nhận xét lý thuyết cần được đặt vào điều kiện lịch sử; nó không thay thế việc kiểm tra tư liệu cụ thể.","choices":["Chấp nhận vì có nhắc đến máy móc.","Bác bỏ mọi vai trò của kỹ thuật.","Yêu cầu bằng chứng về quan hệ lao động, thể chế và diễn biến lịch sử."],"reasons":["Một yếu tố không đủ chứng minh toàn bộ chuỗi nhân quả.","Một ví dụ luôn chứng minh được quy luật cho mọi xã hội.","Phân tích xã hội không cần bằng chứng."],"source":"Karl Marx, Lời tựa Góp phần phê phán khoa kinh tế chính trị (1859) · Marxists Internet Archive"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["marxism-social-change"]},{"id":"marxism-source-reading","topic_id":"marxism","position":5,"content_version":1,"title":"Đọc học thuyết có đối chiếu","stage":"Thử thách","prompt":"Khi trình bày quan điểm của Lênin trong bài năm 1913, cách viết nào phân biệt rõ nguồn với nhận định của người học?","hint_levels":["Tìm cách trình bày vừa trung thành với nguồn, vừa cho phép người đọc đánh giá lập luận."],"explanation":"Dẫn đúng tác giả, thời điểm và luận điểm giúp người đọc kiểm tra nguồn. Phân biệt mô tả với đánh giá là kỹ năng đọc phê phán có thể áp dụng cho mọi học thuyết.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Một văn bản lý luận vừa có khái niệm, lập luận, vừa có bối cảnh và lập trường của tác giả. Hiểu chính xác lập luận không có nghĩa là phải đồng ý với mọi kết luận của tác giả.","choices":["“Mọi người đều phải đồng ý.”","“Lênin lập luận rằng…; cần đối chiếu lập luận với bối cảnh và bằng chứng…”","“Không cần đọc bản gốc vì đã biết tên học thuyết.”"],"reasons":["Nêu nguồn và phân biệt mô tả học thuyết với đánh giá của mình.","Tên tác giả đủ để thay thế bằng chứng.","Hiểu một học thuyết tức là tán thành toàn bộ."],"source":"V. I. Lenin, Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác (1913) · Marxists Internet Archive"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["marxism-source-reading"]},{"id":"marxism-reading","topic_id":"marxism","position":6,"content_version":1,"title":"Đọc học thuyết theo ngữ cảnh","stage":"Thử thách","prompt":"Sắp xếp quy trình đọc một luận điểm lịch sử tư tưởng.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Đọc nguồn và ngữ cảnh trước, tách mô tả tư tưởng khỏi việc tán thành tư tưởng.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Đối chiếu cách diễn giải và phản biện.","Xác định tác giả, văn bản và thời điểm.","Tóm tắt luận điểm kèm đoạn làm căn cứ.","Nêu giới hạn của kết luận."],"target":[1,2,0,3]},"initial_state":{"values":[0,1,2,3]},"skill_ids":["marxism.transfer"]},{"id":"marxism-source-literacy","topic_id":"marxism","position":7,"content_version":1,"title":"Nguồn gốc và diễn giải","stage":"Thử thách","prompt":"Chọn cách làm hỗ trợ việc trình bày một học thuyết chính xác.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Nguồn sơ cấp và đối chiếu giúp kiểm tra cách diễn giải; khác biệt quan điểm cần được trình bày rõ và công bằng.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Trích đúng văn bản và nêu ngữ cảnh.","Gán một câu lan truyền cho tác giả mà không tra nguồn.","Phân biệt nguồn sơ cấp với bình luận về sau.","Bỏ qua mọi cách diễn giải khác."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["marxism.transfer"]},{"id":"painting-value","topic_id":"painting","position":0,"content_version":1,"title":"Sắc độ trước màu sắc","stage":"Nền tảng","prompt":"Ba ô từ trái sang phải chuyển từ tối đến sáng. Thuộc tính nào đang thay đổi rõ nhất?","hint_levels":["Hãy tưởng tượng chụp ba ô bằng ảnh đen trắng."],"explanation":"Ba ô tạo một thang sắc độ. Khi dựng hình khối, phân biệt vùng sáng và vùng tối thường hữu ích trước khi thêm màu.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Sắc độ (value) là mức sáng tối của màu. Sắc màu (hue) là tên màu như đỏ, xanh; độ bão hòa mô tả mức rực hay xỉn. Một tranh có thể giữ cấu trúc sáng tối ngay cả khi chuyển sang thang xám.","choices":["Sắc màu từ đỏ sang xanh.","Sắc độ.","Số lượng vật thể."],"reasons":["Cả ba ô đều có cùng độ sáng.","Màu xám không thể có sắc độ.","Khác biệt chính là lượng sáng tối, dù không có sắc màu rực."],"source":"J. Paul Getty Museum, Understanding Formal Analysis: Elements of Art / Principles of Design","swatches":[4280427042,4287137928,4293848814]},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["painting-value"]},{"id":"painting-form","topic_id":"painting","position":1,"content_version":1,"title":"Từ hình phẳng đến khối","stage":"Nền tảng","prompt":"Bạn muốn hình tròn trông như một quả cầu có nguồn sáng bên trái. Nên làm gì?","hint_levels":["Quan sát hướng nguồn sáng và mặt khối quay ra xa nguồn sáng."],"explanation":"Sự chuyển sắc gợi bề mặt cong. Vị trí vùng sáng phụ thuộc nguồn sáng; không có quy tắc mọi vật đều sáng hoặc tối ở cùng một phía.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Shape là hình có hai chiều; form là khối có ba chiều hoặc cảm giác ba chiều. Trong tranh, chuyển sắc và bóng có thể gợi khối trên mặt phẳng.","choices":["Giữ mọi điểm cùng độ sáng.","Chỉ viết chữ “quả cầu”.","Đặt vùng sáng phía trái và chuyển dần sang tối phía phải."],"reasons":["Chuyển sắc mô tả bề mặt quay dần khỏi nguồn sáng.","Viền tròn tự chứng minh vật có chiều sâu.","Mọi vùng tối luôn phải nằm bên trái."],"source":"J. Paul Getty Museum, Understanding Formal Analysis: Elements of Art / Principles of Design"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["painting-form"]},{"id":"painting-space","topic_id":"painting","position":2,"content_version":1,"title":"Tạo chiều sâu bằng che khuất","stage":"Vận dụng","prompt":"Trong tranh tĩnh vật, quả táo che một phần chiếc cốc. Dấu hiệu này gợi điều gì?","hint_levels":["Tách vị trí tương đối trong tranh khỏi kích thước thật của đồ vật."],"explanation":"Che khuất gợi thứ tự trước–sau. Muốn suy ra kích thước thật còn cần khoảng cách, phối cảnh và các thông tin khác.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Khoảng không trong tranh có thể được gợi qua chồng lớp, tỷ lệ và vị trí. Khi vật A che một phần vật B, người xem thường đọc A là vật ở phía trước.","choices":["Quả táo ở trước chiếc cốc.","Chiếc cốc chắc chắn nhỏ hơn quả táo ngoài đời.","Hai vật không có quan hệ không gian."],"reasons":["Vật có màu ấm luôn nằm phía trước.","Che khuất là dấu hiệu về thứ tự trước–sau, không đủ suy ra kích thước thật.","Vật bị che luôn nhỏ hơn ngoài đời."],"source":"J. Paul Getty Museum, Understanding Formal Analysis: Elements of Art / Principles of Design"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["painting-space"]},{"id":"painting-emphasis","topic_id":"painting","position":3,"content_version":1,"title":"Thiết kế điểm nhấn","stage":"Vận dụng","prompt":"Muốn một chiếc cốc sáng thành điểm nhấn trên nền tối, thay đổi nào trực tiếp tăng tương phản sắc độ?","hint_levels":["So sánh chiếc cốc với vùng nền ngay cạnh, thay vì chỉ nhìn riêng chiếc cốc."],"explanation":"Điểm nhấn có tính tương đối. Tăng chênh lệch sắc độ giữa chủ thể và vùng nền lân cận là một cách hướng mắt người xem.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Nhấn mạnh giúp một vùng thu hút sự chú ý. Tương phản sáng tối, kích thước hoặc màu có thể tạo điểm nhấn; hiệu quả phụ thuộc những gì bao quanh vùng đó.","choices":["Làm mọi vùng sáng bằng nhau.","Giữ chiếc cốc sáng và giảm độ sáng vùng nền cạnh nó.","Thêm nhiều chữ ở mọi góc."],"reasons":["Điểm nhấn cần mọi chi tiết có cùng mức nổi bật.","Càng nhiều vật thể thì tương phản càng lớn.","Chênh lệch sáng tối giữa cốc và nền làm vùng đó nổi bật."],"source":"J. Paul Getty Museum, Understanding Formal Analysis: Elements of Art / Principles of Design","swatches":[4281348144,4294309365,4281348144]},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["painting-emphasis"]},{"id":"painting-rhythm","topic_id":"painting","position":4,"content_version":1,"title":"Nhịp điệu và biến đổi","stage":"Phân tích","prompt":"Một dãy nét cong lặp lại, tăng dần kích thước về phía chủ thể. Mô tả nào sát nhất?","hint_levels":["Tìm yếu tố được giữ lại và thuộc tính thay đổi dần."],"explanation":"Nét cong được lặp lại, còn kích thước thay đổi có tổ chức. Sự phối hợp đó có thể tạo nhịp và hướng quan sát.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Sự lặp lại tạo mẫu hình; nhịp điệu thị giác có thể xuất hiện khi các yếu tố lặp lại và biến đổi có tổ chức. Nhịp điệu giúp dẫn mắt qua bố cục.","choices":["Lặp và biến đổi tạo nhịp dẫn mắt.","Không có mẫu hình vì các nét không giống hệt nhau.","Bố cục chỉ phụ thuộc tên màu."],"reasons":["Nhịp điệu bắt buộc mọi nét phải bằng nhau.","Có yếu tố lặp lại và một quy luật biến đổi có thể quan sát.","Chỉ tranh có âm thanh mới có nhịp điệu."],"source":"J. Paul Getty Museum, Understanding Formal Analysis: Elements of Art / Principles of Design"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["painting-rhythm"]},{"id":"painting-critique","topic_id":"painting","position":5,"content_version":1,"title":"Nhận xét tranh bằng bằng chứng","stage":"Thử thách","prompt":"Nhận xét nào có bằng chứng thị giác rõ nhất cho cảm giác chuyển động?","hint_levels":["Chọn câu mô tả chi tiết nhìn thấy được trước khi suy đoán ý định tác giả."],"explanation":"Đường chéo và sự lặp lại là bằng chứng hình thức. Chúng hỗ trợ cách đọc về chuyển động, nhưng không chứng minh mọi người đều có cảm xúc giống nhau.","mechanism":"reasonedChoice","mechanism_version":1,"evaluator_version":2,"config":{"knowledge":"Phân tích hình thức bắt đầu từ dấu hiệu có thể quan sát: đường nét, sắc độ, màu, khối và không gian. Cần phân biệt điều nhìn thấy với suy luận về ý định của họa sĩ.","choices":["“Tranh này chắc chắn khiến mọi người vui.”","“Họa sĩ hẳn đang vội.”","“Các đường chéo lặp lại dẫn mắt từ góc dưới lên phía trên.”"],"reasons":["Nhận xét chỉ ra hướng và sự lặp lại của đường nét có thể kiểm tra.","Có thể suy ra tâm trạng tác giả chỉ từ tên tranh.","Cảm nhận cá nhân không bao giờ cần giải thích."],"source":"J. Paul Getty Museum, Understanding Formal Analysis: Elements of Art / Principles of Design"},"initial_state":{"answer":-1,"reason":-1},"skill_ids":["painting-critique"]},{"id":"painting-observe","topic_id":"painting","position":6,"content_version":1,"title":"Đọc ngôn ngữ thị giác","stage":"Vận dụng","prompt":"Ghép yếu tố với điều nó mô tả.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Mô tả cụ thể yếu tố thị giác giúp giải thích cảm nhận thay vì chỉ nói đẹp hoặc xấu.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Sắc độ","Bố cục","Tương phản"],"choices":["Cách sắp xếp thành phần","Mức sáng–tối","Mức khác biệt giữa các yếu tố"],"target":[1,0,2]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["painting.transfer"]},{"id":"painting-interpret","topic_id":"painting","position":7,"content_version":1,"title":"Diễn giải dựa vào điều thấy","stage":"Thử thách","prompt":"Chọn phát biểu phân biệt quan sát với diễn giải.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Diễn giải có thể đa dạng nhưng cần căn cứ. Ý định tác giả không thể suy ra chắc chắn chỉ từ một dấu hiệu.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Có thể chỉ ra vị trí vùng sáng trong tranh.","Chỉ nhìn màu đã biết chắc ý định của họa sĩ.","Một diễn giải nên gắn với chi tiết và bối cảnh.","Mọi người buộc phải có cùng cảm xúc."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["painting.transfer"]},{"id":"english-greetings","topic_id":"english","position":0,"content_version":1,"title":"Lời chào đầu tiên","stage":"Nền tảng","prompt":"Ghép câu tiếng Anh với ý nghĩa phù hợp.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Hello mở đầu cuộc trò chuyện; Thank you bày tỏ lời cảm ơn; Goodbye kết thúc cuộc gặp.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Hello!","Thank you.","Goodbye!"],"choices":["Cảm ơn.","Tạm biệt!","Xin chào!"],"target":[2,0,1]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["english.transfer"]},{"id":"english-listen","topic_id":"english","position":1,"content_version":1,"title":"Nghe và tìm hành động","stage":"Nền tảng","prompt":"Nghe câu tiếng Anh rồi chọn ý đúng. Có thể nghe chậm, nghe lại hoặc mở bản chữ.","hint_levels":["Chú ý hành động, thời gian và những từ phủ định trong câu."],"explanation":"Open là mở; blue mô tả màu xanh của book. Hiểu cả động từ lẫn tính từ giúp làm đúng yêu cầu.","mechanism":"listeningChoice","mechanism_version":1,"evaluator_version":2,"config":{"text":"Please open the blue book.","choices":["Đóng quyển sách xanh.","Mở quyển sách xanh.","Mở quyển sách đỏ."],"target":1},"initial_state":{"answer":-1,"experienced":false},"skill_ids":["english.transfer"]},{"id":"english-sentence","topic_id":"english","position":2,"content_version":1,"title":"Xây câu từ những mảnh ghép","stage":"Vận dụng","prompt":"Sắp xếp thành câu kể: Tôi đọc sách mỗi ngày.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"I read books every day: chủ ngữ + động từ + tân ngữ + cụm thời gian.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["every day.","read","I","books"],"target":[2,1,3,0]},"initial_state":{"values":[0,1,2,3]},"skill_ids":["english.transfer"]},{"id":"english-introduce","topic_id":"english","position":3,"content_version":1,"title":"Nói lời giới thiệu","stage":"Vận dụng","prompt":"Luyện câu “Hello, my name is Alex.” Nói hoặc nhập câu; chú ý thứ tự từ.","hint_levels":["Nghe câu mẫu, nói từng cụm ngắn. Có thể nhập câu nếu không dùng micro."],"explanation":"My name is dùng để giới thiệu tên. Máy chỉ đối chiếu các từ nhận dạng, không đánh giá giọng hay mức độ phát âm.","mechanism":"speechPractice","mechanism_version":1,"evaluator_version":2,"config":{"text":"Hello, my name is Alex.","accepted":["Hello my name is Alex"]},"initial_state":{"response":""},"skill_ids":["english.transfer"]},{"id":"english-inference","topic_id":"english","position":4,"content_version":1,"title":"Nghe để suy luận","stage":"Thử thách","prompt":"Nghe câu tiếng Anh rồi chọn ý đúng. Có thể nghe chậm, nghe lại hoặc mở bản chữ.","hint_levels":["Chú ý hành động, thời gian và những từ phủ định trong câu."],"explanation":"Used to nói về thói quen cũ; but now chỉ sự thay đổi; because giải thích lý do.","mechanism":"listeningChoice","mechanism_version":1,"evaluator_version":2,"config":{"text":"I used to walk to school, but now I take the bus because it is farther away.","choices":["Hiện tại người nói luôn đi bộ.","Người nói đổi sang xe buýt vì trường xa hơn.","Người nói chưa từng đi bộ."],"target":1},"initial_state":{"answer":-1,"experienced":false},"skill_ids":["english.transfer"]},{"id":"english-request","topic_id":"english","position":5,"content_version":1,"title":"Nói lịch sự trong tình huống mới","stage":"Thử thách","prompt":"Bạn chưa hiểu lời giải. Luyện hỏi: “Could you explain that again, please?”","hint_levels":["Nghe câu mẫu, nói từng cụm ngắn. Có thể nhập câu nếu không dùng micro."],"explanation":"Could you … please là cách yêu cầu lịch sự. Again cho biết bạn muốn nghe giải thích thêm lần nữa.","mechanism":"speechPractice","mechanism_version":1,"evaluator_version":2,"config":{"text":"Could you explain that again, please?","accepted":["Could you explain that again please"]},"initial_state":{"response":""},"skill_ids":["english.transfer"]},{"id":"vietnamese-meaning","topic_id":"vietnamese","position":0,"content_version":1,"title":"Từ ngữ và ngữ cảnh","stage":"Nền tảng","prompt":"Ghép từ với nghĩa trong câu nói hằng ngày.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Hiểu chính xác nghĩa của động từ giúp biến lời hướng dẫn thành hành động.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Quan sát","Hợp tác","Kiên trì"],"choices":["Cùng làm để đạt mục tiêu.","Tiếp tục cố gắng dù gặp khó.","Nhìn và ghi nhận chi tiết."],"target":[2,0,1]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["vietnamese.transfer"]},{"id":"vietnamese-tone","topic_id":"vietnamese","position":1,"content_version":1,"title":"Chọn lời nói phù hợp","stage":"Nền tảng","prompt":"Phân loại lời nói theo mục đích giao tiếp.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Lời nhờ, cảm ơn và xin lỗi có mục đích khác nhau; lịch sự còn phụ thuộc giọng điệu và tình huống.","mechanism":"categorySort","mechanism_version":1,"evaluator_version":2,"config":{"items":["Bạn giúp mình với được không?","Cảm ơn bạn đã chờ.","Mình xin lỗi vì đến muộn."],"choices":["Nhờ giúp đỡ","Cảm ơn","Xin lỗi"],"target":[0,1,2]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["vietnamese.transfer"]},{"id":"vietnamese-story","topic_id":"vietnamese","position":2,"content_version":1,"title":"Kể chuyện có mạch","stage":"Vận dụng","prompt":"Sắp xếp ba sự việc để câu chuyện trồng cây có trình tự hợp lý.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Trình tự thời gian giúp người nghe theo được diễn biến: gieo và chăm → nảy mầm → cây trưởng thành cho quả.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Hạt nảy mầm.","Thu hoạch quả.","Gieo hạt và chăm sóc."],"target":[2,0,1]},"initial_state":{"values":[0,1,2]},"skill_ids":["vietnamese.transfer"]},{"id":"vietnamese-connectors","topic_id":"vietnamese","position":3,"content_version":1,"title":"Nối ý cho rõ nghĩa","stage":"Nền tảng","prompt":"Chọn từ nối để thể hiện đúng quan hệ trong hai câu.","hint_levels":["Đọc cả câu trước và sau chỗ trống; mỗi từ phải đúng cả nghĩa và ngữ cảnh."],"explanation":"Nên diễn tả hệ quả; mặc dù mở đầu quan hệ nhượng bộ, điều xảy ra trái với kỳ vọng.","mechanism":"clozeBank","mechanism_version":1,"evaluator_version":2,"config":{"items":["Trời mưa, ___ đường ướt.","___ trời mưa, chúng em vẫn đến đúng giờ."],"choices":["nên","Mặc dù","hoặc"],"target":[0,1]},"initial_state":{"values":[-1,-1]},"skill_ids":["vietnamese.transfer"]},{"id":"vietnamese-argument","topic_id":"vietnamese","position":4,"content_version":1,"title":"Lập luận bằng bằng chứng","stage":"Thử thách","prompt":"Kết luận: “Lớp nên giữ góc đọc sách.” Chọn các dữ kiện trực tiếp hỗ trợ ích lợi của góc đọc.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Số lượt mượn và khảo sát đúng đối tượng hỗ trợ lập luận; khẳng định tuyệt đối và màu tường không chứng minh nhu cầu.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Nhật ký cho thấy 18/25 bạn mượn sách tuần này.","Một bạn nói: mọi lớp trên đời đều thích sách.","Khảo sát lớp: 20/25 bạn muốn tiếp tục dùng góc đọc.","Tường lớp được sơn màu xanh."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["vietnamese.transfer"]},{"id":"vietnamese-revise","topic_id":"vietnamese","position":5,"content_version":1,"title":"Biên tập một thông điệp","stage":"Thử thách","prompt":"Sắp xếp quy trình viết lời đề nghị có trách nhiệm.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Xác định người đọc → viết có lý do → biên tập → gửi giúp thông điệp rõ ràng và tôn trọng.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Kiểm tra giọng điệu và lỗi diễn đạt.","Xác định người đọc và mục đích.","Viết đề nghị kèm lý do cụ thể.","Gửi sau khi đọc lại."],"target":[1,2,0,3]},"initial_state":{"values":[0,1,2,3]},"skill_ids":["vietnamese.transfer"]},{"id":"biology-parts","topic_id":"biology","position":0,"content_version":1,"title":"Cây sống bằng những bộ phận nào?","stage":"Nền tảng","prompt":"Ghép bộ phận cây với một chức năng chính.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Các bộ phận phối hợp: rễ hấp thụ, thân nâng đỡ và vận chuyển, lá quang hợp.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Rễ","Lá","Thân"],"choices":["Nâng đỡ và vận chuyển.","Hấp thụ nước và chất khoáng.","Quang hợp khi có ánh sáng."],"target":[1,2,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["biology.transfer"]},{"id":"biology-food","topic_id":"biology","position":1,"content_version":1,"title":"Vai trò trong hệ sinh thái","stage":"Nền tảng","prompt":"Phân loại theo vai trò trong chuỗi thức ăn này.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Cỏ tạo chất hữu cơ; thỏ tiêu thụ; nấm phân giải vật chất. Một hệ sinh thái cần nhiều vai trò.","mechanism":"categorySort","mechanism_version":1,"evaluator_version":2,"config":{"items":["Cỏ","Thỏ","Nấm phân giải lá rụng"],"choices":["Sinh vật sản xuất","Sinh vật tiêu thụ","Sinh vật phân giải"],"target":[0,1,2]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["biology.transfer"]},{"id":"biology-cycle","topic_id":"biology","position":2,"content_version":1,"title":"Theo dấu vòng đời","stage":"Vận dụng","prompt":"Bắt đầu từ hạt, sắp xếp vòng đời cây đậu trong điều kiện phù hợp.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Nảy mầm → cây non → cây ra hoa → quả và hạt mới. Không phải mọi hạt đều sống sót trong tự nhiên.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Cây ra hoa.","Hạt nảy mầm.","Quả có hạt mới.","Cây non phát triển."],"target":[1,3,0,2]},"initial_state":{"values":[0,1,2,3]},"skill_ids":["biology.transfer"]},{"id":"biology-photosynthesis","topic_id":"biology","position":3,"content_version":1,"title":"Hoàn thiện mô hình quang hợp","stage":"Nền tảng","prompt":"Điền tên chất vào mô hình giản lược.","hint_levels":["Đọc cả câu trước và sau chỗ trống; mỗi từ phải đúng cả nghĩa và ngữ cảnh."],"explanation":"Trong quang hợp, cây dùng carbon dioxide và nước với năng lượng ánh sáng để tạo chất hữu cơ, giải phóng oxygen.","mechanism":"clozeBank","mechanism_version":1,"evaluator_version":2,"config":{"items":["Cây hấp thụ khí ___ để tạo chất hữu cơ.","Quang hợp giải phóng khí ___."],"choices":["oxygen","carbon dioxide","nitrogen"],"target":[1,0]},"initial_state":{"values":[-1,-1]},"skill_ids":["biology.transfer"]},{"id":"biology-growth","topic_id":"biology","position":4,"content_version":1,"title":"Phòng thí nghiệm hai yếu tố","stage":"Thử thách","prompt":"Đây là mô hình điểm tài nguyên, không dự báo tốc độ sinh trưởng thật của cây. Mô hình giản lược: kết quả = Ánh sáng × Nước. Mỗi tham số từ 0 đến 3. Tạo kết quả 6, dự đoán rồi chạy thử.","hint_levels":["Đổi một yếu tố mỗi lần để nhìn rõ tác động. Ghi nhớ giới hạn 0–3."],"explanation":"Các cặp 2 × 3 và 3 × 2 đều tạo 6 điểm trong mô hình. Cây thật còn phụ thuộc nhiệt độ, dinh dưỡng và giới hạn sinh học.","mechanism":"causalExperiment","mechanism_version":1,"evaluator_version":2,"config":{"axes":["Ánh sáng","Nước"],"goal":6},"initial_state":{"x":0,"y":0,"prediction":-1,"observed":[],"trials":[]},"skill_ids":["biology.transfer"]},{"id":"biology-control","topic_id":"biology","position":5,"content_version":1,"title":"Thiết kế thí nghiệm công bằng","stage":"Thử thách","prompt":"Để kiểm tra tác động của ánh sáng lên cây cùng loài, chọn cách thiết kế giúp tách riêng yếu tố ánh sáng.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Kiểm soát các yếu tố khác và lặp mẫu giúp giảm nhiễu. Chọn mẫu sau khi biết kết quả tạo thiên lệch.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Giữ giống, đất và lượng nước tương đương.","Đổi cả ánh sáng lẫn loại đất.","Dùng nhiều cây cho mỗi nhóm.","Chỉ đo một cây khỏe nhất sau khi biết kết quả."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["biology.transfer"]},{"id":"chemistry-states","topic_id":"chemistry","position":0,"content_version":1,"title":"Vật chất quanh ta","stage":"Nền tảng","prompt":"Phân loại ở điều kiện thường được mô tả.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Cùng một chất có thể ở nhiều thể tùy nhiệt độ và áp suất. Hơi nước là khí, không phải các giọt sương nhìn thấy.","mechanism":"categorySort","mechanism_version":1,"evaluator_version":2,"config":{"items":["Viên nước đá ở −5°C","Nước trong cốc ở 25°C","Hơi nước"],"choices":["Rắn","Lỏng","Khí"],"target":[0,1,2]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["chemistry.transfer"]},{"id":"chemistry-tools","topic_id":"chemistry","position":1,"content_version":1,"title":"Dụng cụ và chức năng","stage":"Nền tảng","prompt":"Ghép dụng cụ với chức năng, chỉ làm thí nghiệm trong app.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Chọn đúng dụng cụ và đơn vị trước khi đo giúp tránh nhầm khối lượng, thể tích và nhiệt độ.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Nhiệt kế","Cân","Ống đong"],"choices":["Đo khối lượng","Đo thể tích chất lỏng","Đo nhiệt độ"],"target":[2,0,1]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["chemistry.transfer"]},{"id":"chemistry-water","topic_id":"chemistry","position":2,"content_version":1,"title":"Đi qua các thể","stage":"Vận dụng","prompt":"Bắt đầu từ nước đá, sắp xếp quá trình khi cấp nhiệt liên tục ở áp suất thường.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Nóng chảy và sôi là chuyển thể; nhiệt độ không tăng liên tục trong suốt quá trình chuyển thể của chất tinh khiết.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Nước lỏng nóng lên.","Nước đá nhận nhiệt và nóng chảy.","Nước sôi, chuyển dần thành hơi."],"target":[1,0,2]},"initial_state":{"values":[0,1,2]},"skill_ids":["chemistry.transfer"]},{"id":"chemistry-atoms","topic_id":"chemistry","position":3,"content_version":1,"title":"Đếm nguyên tử trong phân tử","stage":"Nền tảng","prompt":"Điền số nguyên tử cho mỗi công thức.","hint_levels":["Đọc cả câu trước và sau chỗ trống; mỗi từ phải đúng cả nghĩa và ngữ cảnh."],"explanation":"Chỉ số dưới thuộc nguyên tố ngay trước nó. H₂O có 2 H và 1 O; CO₂ có 1 C và 2 O.","mechanism":"clozeBank","mechanism_version":1,"evaluator_version":2,"config":{"items":["Số H trong H₂O","Số O trong CO₂","Tổng nguyên tử trong H₂O"],"choices":["1","2","3"],"target":[1,1,2]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["chemistry.transfer"]},{"id":"chemistry-conservation","topic_id":"chemistry","position":4,"content_version":1,"title":"Bảo toàn trong mô hình hạt","stage":"Thử thách","prompt":"Chia 10 hạt mô phỏng vào ba hộp; không tạo thêm hay làm mất hạt. Phân bổ đúng 10 đơn vị; mỗi mục phải đạt mức tối thiểu ghi bên dưới.","hint_levels":["Đáp ứng các mức tối thiểu trước, rồi phân bổ phần còn lại. Có thể có nhiều phương án đúng."],"explanation":"Các cách phân chia có thể khác nhau nhưng tổng luôn là 10. Đây là mô hình đếm hạt, không phải mô tả một phản ứng hóa học cụ thể.","mechanism":"resourceBudget","mechanism_version":1,"evaluator_version":2,"config":{"items":["Hộp A","Hộp B","Hộp C"],"minima":[2,3,1]},"initial_state":{"values":[0,0,0]},"skill_ids":["chemistry.transfer"]},{"id":"chemistry-claim","topic_id":"chemistry","position":5,"content_version":1,"title":"Quan sát hay kết luận vội?","stage":"Thử thách","prompt":"Một cốc có bọt khi khuấy. Chọn các nhận định khoa học hợp lý.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Một dấu hiệu riêng lẻ chưa luôn chứng minh phản ứng. Cần kiểm tra giả thuyết thay thế và đặc tính chất.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Bọt có thể là khí thoát ra hoặc không khí bị cuốn vào.","Chỉ thấy bọt đã đủ khẳng định tạo chất mới.","Cần thêm dữ kiện về chất ban đầu và sản phẩm.","Mọi biến đổi đều không thể đảo ngược."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["chemistry.transfer"]},{"id":"astronomy-objects","topic_id":"astronomy","position":0,"content_version":1,"title":"Nhận diện bầu trời","stage":"Nền tảng","prompt":"Ghép thiên thể với mô tả phù hợp.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Mặt Trời là sao; Trái Đất là hành tinh; Mặt Trăng là vệ tinh tự nhiên. Ánh sáng Mặt Trăng chủ yếu là ánh sáng Mặt Trời phản xạ.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Mặt Trời","Trái Đất","Mặt Trăng"],"choices":["Vệ tinh tự nhiên của Trái Đất","Ngôi sao","Hành tinh"],"target":[1,2,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["astronomy.transfer"]},{"id":"astronomy-scale","topic_id":"astronomy","position":1,"content_version":1,"title":"Từ gần đến xa","stage":"Nền tảng","prompt":"Sắp xếp khoảng cách điển hình tính từ Trái Đất, từ gần đến xa.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Mặt Trăng gần hơn Mặt Trời rất nhiều; các sao khác ở xa hơn Mặt Trời nhiều bậc độ lớn.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Mặt Trời","Ngôi sao gần nhất ngoài Mặt Trời","Mặt Trăng"],"target":[2,0,1]},"initial_state":{"values":[0,1,2]},"skill_ids":["astronomy.transfer"]},{"id":"astronomy-motion","topic_id":"astronomy","position":2,"content_version":1,"title":"Chuyển động và hiện tượng","stage":"Vận dụng","prompt":"Ghép chuyển động hoặc đặc điểm với hệ quả chính.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Ngày đêm do tự quay; năm do chu kỳ quỹ đạo; các mùa chủ yếu do trục nghiêng làm thay đổi góc chiếu và độ dài ngày.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Trái Đất tự quay","Trái Đất quay quanh Mặt Trời","Trục nghiêng và quỹ đạo quanh Mặt Trời"],"choices":["Một năm","Ngày và đêm","Chu kỳ các mùa"],"target":[1,0,2]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["astronomy.transfer"]},{"id":"astronomy-moon","topic_id":"astronomy","position":3,"content_version":1,"title":"Vì sao Mặt Trăng đổi hình?","stage":"Nền tảng","prompt":"Hoàn thiện lời giải thích pha Mặt Trăng.","hint_levels":["Đọc cả câu trước và sau chỗ trống; mỗi từ phải đúng cả nghĩa và ngữ cảnh."],"explanation":"Pha Mặt Trăng do hình học nhìn phần sáng. Bóng Trái Đất gây nguyệt thực, không phải các pha thường ngày.","mechanism":"clozeBank","mechanism_version":1,"evaluator_version":2,"config":{"items":["Mặt Trăng được chiếu sáng bởi ___.","Ta nhìn thấy phần sáng khác nhau khi vị trí ___ thay đổi."],"choices":["Mặt Trời","ba thiên thể","bóng Trái Đất mỗi đêm"],"target":[0,1]},"initial_state":{"values":[-1,-1]},"skill_ids":["astronomy.transfer"]},{"id":"astronomy-mission","topic_id":"astronomy","position":4,"content_version":1,"title":"Thiết kế nhiệm vụ thám hiểm","stage":"Thử thách","prompt":"Trong trò chơi nhiệm vụ, chia 10 đơn vị tải trọng; đây là ràng buộc giả lập. Phân bổ đúng 10 đơn vị; mỗi mục phải đạt mức tối thiểu ghi bên dưới.","hint_levels":["Đáp ứng các mức tối thiểu trước, rồi phân bổ phần còn lại. Có thể có nhiều phương án đúng."],"explanation":"Nhiệm vụ có nhiều phương án khả thi. Tối ưu một mục mà bỏ năng lượng hoặc liên lạc có thể làm cả hệ thống thất bại.","mechanism":"resourceBudget","mechanism_version":1,"evaluator_version":2,"config":{"items":["Thiết bị khoa học","Năng lượng","Liên lạc"],"minima":[3,3,2]},"initial_state":{"values":[0,0,0]},"skill_ids":["astronomy.transfer"]},{"id":"astronomy-seasons","topic_id":"astronomy","position":5,"content_version":1,"title":"Giải thích mùa bằng bằng chứng","stage":"Thử thách","prompt":"Chọn dữ kiện hỗ trợ mô hình mùa do trục nghiêng thay vì chỉ do khoảng cách đến Mặt Trời.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Mùa đối lập giữa hai bán cầu và độ dài ngày thay đổi phù hợp mô hình trục nghiêng.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Hai bán cầu có các mùa đối lập.","Độ dài ban ngày thay đổi theo mùa ở nhiều vĩ độ.","Mùa hè vì Trái Đất ở gần Mặt Trời nhất tại mọi nơi.","Mặt Trời tự tắt vào mùa đông."],"target":[0,1]},"initial_state":{"selected":[]},"skill_ids":["astronomy.transfer"]},{"id":"finance-needs","topic_id":"finance","position":0,"content_version":1,"title":"Cần hay muốn trong tình huống này?","stage":"Nền tảng","prompt":"Gia đình đã có đủ đồ chơi; phân loại các khoản sau trong tình huống đi học.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Nhu cầu và mong muốn phụ thuộc hoàn cảnh. Ở tình huống này nước và vở cần cho sinh hoạt, học tập.","mechanism":"categorySort","mechanism_version":1,"evaluator_version":2,"config":{"items":["Nước uống an toàn","Đồ chơi phiên bản mới","Vở để học khi đã hết"],"choices":["Nhu cầu thiết yếu","Mong muốn thêm"],"target":[0,1,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["finance.transfer"]},{"id":"finance-terms","topic_id":"finance","position":1,"content_version":1,"title":"Ngôn ngữ của ngân sách","stage":"Nền tảng","prompt":"Ghép khái niệm với ý nghĩa.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Ngân sách theo dõi khoản vào, khoản ra và phần giữ lại, không chỉ số tiền đang có.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Thu nhập","Chi tiêu","Tiết kiệm"],"choices":["Phần giữ lại cho mục tiêu sau","Khoản nhận được","Khoản dùng để mua hoặc thanh toán"],"target":[1,2,0]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["finance.transfer"]},{"id":"finance-plan","topic_id":"finance","position":2,"content_version":1,"title":"Từ mục tiêu đến hành động","stage":"Vận dụng","prompt":"Sắp xếp quy trình dành tiền cho một cuốn sách.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Mục tiêu cụ thể → kế hoạch theo thời gian → theo dõi thực tế. Điều chỉnh kế hoạch khi điều kiện thay đổi.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Theo dõi và điều chỉnh mỗi tuần.","Xác định giá sách và thời hạn.","Tính số cần để dành mỗi tuần."],"target":[1,2,0]},"initial_state":{"values":[0,1,2]},"skill_ids":["finance.transfer"]},{"id":"finance-change","topic_id":"finance","position":3,"content_version":1,"title":"Tính phần còn lại","stage":"Nền tảng","prompt":"Trong cửa hàng giả lập, mỗi đơn vị là một điểm trò chơi.","hin