nce.transfer"]},{"id":"digital-private","topic_id":"digital","position":0,"content_version":1,"title":"Điều gì nên giữ riêng?","stage":"Nền tảng","prompt":"Phân loại khi đăng công khai trên mạng.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Mật khẩu và địa chỉ chính xác cần bảo vệ; kể cả bài vẽ cũng nên xem lại quyền riêng tư và sự đồng ý của người liên quan.","mechanism":"categorySort","mechanism_version":1,"evaluator_version":2,"config":{"items":["Mật khẩu đăng nhập","Địa chỉ nhà chính xác","Bài vẽ không có thông tin cá nhân"],"choices":["Thông tin nhạy cảm","Có thể chia sẻ sau khi xem xét"],"target":[0,0,1]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["digital.transfer"]},{"id":"digital-tools","topic_id":"digital","position":1,"content_version":1,"title":"Chọn công cụ đúng việc","stage":"Nền tảng","prompt":"Ghép nhu cầu với công cụ phù hợp nhất.","hint_levels":["Ghép theo quan hệ được hỏi; không dựa vào vị trí của thẻ."],"explanation":"Chọn công cụ theo nhiệm vụ giúp làm việc hiệu quả hơn; không công cụ nào luôn đúng cho mọi việc.","mechanism":"matchPairs","mechanism_version":1,"evaluator_version":2,"config":{"items":["Tính tổng bảng số","Viết bản nháp","Tìm thông tin trên web"],"choices":["Trình soạn thảo","Công cụ tìm kiếm","Bảng tính"],"target":[2,0,1]},"initial_state":{"values":[-1,-1,-1]},"skill_ids":["digital.transfer"]},{"id":"digital-verify","topic_id":"digital","position":2,"content_version":1,"title":"Dừng lại trước khi chia sẻ","stage":"Vận dụng","prompt":"Sắp xếp các bước kiểm tra tin gây sốc.","hint_levels":["Dùng mũi tên hoặc kéo thẻ để đổi thứ tự; kiểm tra quan hệ trước–sau."],"explanation":"Đọc nguồn gốc → đối chiếu → quyết định chia sẻ; tiêu đề và lượt thích không thay cho bằng chứng.","mechanism":"sequenceTiles","mechanism_version":1,"evaluator_version":2,"config":{"items":["Đối chiếu nguồn độc lập và ngày đăng.","Chỉ chia sẻ khi đã hiểu ngữ cảnh.","Đọc toàn bài và xác định nguồn gốc."],"target":[2,0,1]},"initial_state":{"values":[0,1,2]},"skill_ids":["digital.transfer"]},{"id":"digital-ai","topic_id":"digital","position":3,"content_version":1,"title":"Hiểu giới hạn của AI","stage":"Nền tảng","prompt":"Điền từ vào quy tắc dùng trợ lý học tập.","hint_levels":["Đọc cả câu trước và sau chỗ trống; mỗi từ phải đúng cả nghĩa và ngữ cảnh."],"explanation":"Văn bản trôi chảy không đảm bảo đúng. Kiểm tra nguồn, phép tính và ngữ cảnh, nhất là thông tin quan trọng.","mechanism":"clozeBank","mechanism_version":1,"evaluator_version":2,"config":{"items":["AI có thể tạo câu trả lời ___ dù nghe tự tin.","Thông tin quan trọng cần được ___ bằng nguồn phù hợp."],"choices":["sai","kiểm chứng","luôn đúng"],"target":[0,1]},"initial_state":{"values":[-1,-1]},"skill_ids":["digital.transfer"]},{"id":"digital-phishing","topic_id":"digital","position":4,"content_version":1,"title":"Điều tra tin nhắn giả mạo","stage":"Thử thách","prompt":"Tin nhắn yêu cầu mật khẩu để “xác minh tài khoản”. Chọn cách xử lý phù hợp.","hint_levels":["Có thể chọn nhiều thẻ. Phân biệt dữ kiện quan sát được với ý kiến và kết luận vượt bằng chứng."],"explanation":"Đi vào ứng dụng hoặc kênh chính thức thay vì liên kết đáng ngờ. Không chia sẻ mật khẩu hay mã xác nhận.","mechanism":"evidenceBoard","mechanism_version":1,"evaluator_version":2,"config":{"items":["Mở app bằng biểu tượng quen thuộc để kiểm tra.","Gửi mật khẩu trong hộp chat.","Báo cho người lớn đáng tin và dùng kênh hỗ trợ chính thức.","Bấm mọi liên kết để xem có thật không."],"target":[0,2]},"initial_state":{"selected":[]},"skill_ids":["digital.transfer"]},{"id":"digital-project","topic_id":"digital","position":5,"content_version":1,"title":"Lập kế hoạch sản phẩm số","stage":"Thử thách","prompt":"Chia 10 phiên làm việc cho dự án nhóm giả lập. Phân bổ đúng 10 đơn vị; mỗi mục phải đạt mức tối thiểu ghi bên dưới.","hint_levels":["Đáp ứng các mức tối thiểu trước, rồi phân bổ phần còn lại. Có thể có nhiều phương án đúng."],"explanation":"Dành thời gian cho nhu cầu và kiểm tra giúp tránh xây nhanh một sản phẩm không dùng được; có nhiều cách phân bổ hợp lệ.","mechanism":"resourceBudget","mechanism_version":1,"evaluator_version":2,"config":{"items":["Khám phá nhu cầu","Tạo sản phẩm","Kiểm tra và sửa"],"minima":[2,4,2]},"initial_state":{"values":[0,0,0]},"skill_ids":["digital.transfer"]}],"verification":"requires_evaluator_parity_and_release"}'::jsonb;
  entries jsonb; mechanism_name text; topic jsonb; activity jsonb;
  release public.content_releases; manifest jsonb; version public.activity_versions;
BEGIN
  FOR mechanism_name IN SELECT DISTINCT x->>'mechanism'
    FROM jsonb_array_elements(catalog->'activities') x WHERE (x->>'evaluator_version')::int=2
  LOOP
    SELECT jsonb_agg(x-'topic_id'-'position') INTO entries
      FROM jsonb_array_elements(catalog->'activities') x
      WHERE x->>'mechanism'=mechanism_name AND (x->>'evaluator_version')::int=2;
    IF EXISTS(SELECT 1 FROM private.evaluator_versions ev WHERE ev.mechanism=mechanism_name
      AND ev.version=2 AND (ev.implementation_hash<>'2026751a785c0d39247ca3fc69de71c42f5f47ae87c4340b25a24ecf6bed4b45'
        OR ev.input_schema IS DISTINCT FROM jsonb_build_object('activities',entries,'max_state_bytes',65536)))
    THEN RAISE EXCEPTION 'Evaluator v2 differs from immutable registered implementation'; END IF;
    INSERT INTO private.evaluator_versions(mechanism,version,handler_key,implementation_hash,input_schema,status)
      VALUES(mechanism_name,2,'learning-api:dart-v2','2026751a785c0d39247ca3fc69de71c42f5f47ae87c4340b25a24ecf6bed4b45',
        jsonb_build_object('activities',entries,'max_state_bytes',65536),'active') ON CONFLICT DO NOTHING;
  END LOOP;
  FOR topic IN SELECT value FROM jsonb_array_elements(catalog->'topics') LOOP
    INSERT INTO public.topics(id,title,subtitle,subject,icon_key,action_label,sort_order,status)
      VALUES(topic->>'id',topic->>'title',topic->>'subtitle',topic->>'subject',topic->>'icon_key',
        topic->>'action_label',0,'active') ON CONFLICT DO NOTHING;
  END LOOP;
  FOR activity IN SELECT value FROM jsonb_array_elements(catalog->'activities') LOOP
    INSERT INTO public.activities(id,topic_id) VALUES(activity->>'id',activity->>'topic_id') ON CONFLICT DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.activities a WHERE a.id=activity->>'id' AND a.topic_id=activity->>'topic_id')
    THEN RAISE EXCEPTION 'Activity topic mismatch'; END IF;
    SELECT * INTO version FROM public.activity_versions av WHERE av.activity_id=activity->>'id'
      AND av.content_version=(activity->>'content_version')::int;
    IF FOUND THEN
      IF NOT private.supported_activity(version) OR version.config IS DISTINCT FROM activity->'config'
        OR version.initial_state IS DISTINCT FROM activity->'initial_state'
        OR version.mechanism IS DISTINCT FROM activity->>'mechanism'
      THEN RAISE EXCEPTION 'Existing activity is incompatible: %',activity->>'id'; END IF;
    ELSE
      INSERT INTO public.activity_versions(activity_id,content_version,title,stage,prompt,hint_levels,explanation,
        mechanism,mechanism_version,evaluator_version,config,initial_state,skill_ids)
        VALUES(activity->>'id',(activity->>'content_version')::int,activity->>'title',activity->>'stage',
          activity->>'prompt',activity->'hint_levels',activity->>'explanation',activity->>'mechanism',
          (activity->>'mechanism_version')::int,(activity->>'evaluator_version')::int,
          activity->'config',activity->'initial_state',ARRAY(SELECT jsonb_array_elements_text(activity->'skill_ids')));
    END IF;
  END LOOP;
  SELECT * INTO release FROM public.content_releases WHERE version_label='frontend-complete-2026-11-03' FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.content_releases(version_label,min_app_version)
      VALUES('frontend-complete-2026-11-03','1.3.2') RETURNING * INTO release;
    INSERT INTO public.release_activities(release_id,activity_id,content_version,topic_id,position,required)
      SELECT release.id,a->>'id',(a->>'content_version')::int,a->>'topic_id',(a->>'position')::int,true
      FROM jsonb_array_elements(catalog->'activities') a;
  END IF;
  IF (SELECT count(*) FROM public.release_activities ra WHERE ra.release_id=release.id)<>139
    OR EXISTS(SELECT 1 FROM public.release_activities ra JOIN public.activity_versions av
      ON av.activity_id=ra.activity_id AND av.content_version=ra.content_version
      WHERE ra.release_id=release.id AND NOT private.supported_activity(av))
  THEN RAISE EXCEPTION 'Expanded release lacks verified evaluator coverage'; END IF;
  IF release.status='draft' THEN
    UPDATE public.activity_versions av SET status='published',published_at=now() WHERE av.status='draft'
      AND EXISTS(SELECT 1 FROM public.release_activities ra WHERE ra.release_id=release.id
        AND ra.activity_id=av.activity_id AND ra.content_version=av.content_version);
    SELECT jsonb_agg(to_jsonb(ra) ORDER BY ra.topic_id,ra.position) INTO manifest
      FROM public.release_activities ra WHERE ra.release_id=release.id;
    UPDATE public.content_releases SET status='published',published_at=now(),
      manifest_hash=encode(extensions.digest(convert_to(manifest::text,'UTF8'),'sha256'),'hex') WHERE id=release.id;
    UPDATE public.topics t SET status='active' WHERE t.status='draft'
      AND EXISTS(SELECT 1 FROM public.release_activities ra WHERE ra.release_id=release.id AND ra.topic_id=t.id);
    INSERT INTO private.admin_audit_logs(actor_kind,action,target_type,target_id,request_id,summary)
      VALUES('system','content.publish','release',release.id::text,gen_random_uuid(),
        jsonb_build_object('version_label',release.version_label,'activities',139,'reason','Full mobile/backend parity'));
  END IF;
END $catalog$;

-- Archive/draft controls discovery, independently of immutable session history.
-- Return status explicitly; old clients retain the same response shape.
CREATE OR REPLACE FUNCTION private.learning_catalog(app_version text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid := private.learning_actor(); release public.content_releases;
BEGIN
  IF app_version IS NULL OR app_version !~ '^\d+\.\d+\.\d+$' THEN
    RAISE EXCEPTION 'Invalid app version' USING ERRCODE='22023'; END IF;
  SELECT * INTO release FROM public.content_releases r WHERE r.status='published'
    AND string_to_array(r.min_app_version,'.')::int[]<=string_to_array(app_version,'.')::int[]
    ORDER BY published_at DESC,id DESC LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('release',NULL,'topics','[]'::jsonb,'activities','[]'::jsonb); END IF;
  RETURN jsonb_build_object('release',to_jsonb(release),
    'topics',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.sort_order,t.id),'[]') FROM public.topics t
      WHERE EXISTS(SELECT 1 FROM public.release_activities ra WHERE ra.release_id=release.id AND ra.topic_id=t.id)),
    'activities',(SELECT coalesce(jsonb_agg(to_jsonb(av)||jsonb_build_object('topic_id',ra.topic_id,'position',ra.position,
      'required',ra.required) ORDER BY ra.topic_id,ra.position),'[]') FROM public.release_activities ra
      JOIN public.activity_versions av ON av.activity_id=ra.activity_id AND av.content_version=ra.content_version
      WHERE ra.release_id=release.id));
END $$;
REVOKE ALL ON FUNCTION private.learning_catalog(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.learning_catalog(text) TO authenticated;

CREATE OR REPLACE FUNCTION private.guard_topic_session_start()
RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
  IF NEW.source='mobile' AND NOT EXISTS(SELECT 1 FROM public.topics t WHERE t.id=NEW.topic_id AND t.status='active')
  THEN RAISE EXCEPTION 'Lesson unavailable' USING ERRCODE='22023'; END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.guard_topic_session_start() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS topic_session_start ON public.learning_sessions;
CREATE TRIGGER topic_session_start BEFORE INSERT ON public.learning_sessions
  FOR EACH ROW EXECUTE FUNCTION private.guard_topic_session_start();
NOTIFY pgrst,'reload schema';
